import type { CRDocument } from '../types';

export const docs: CRDocument[] = [
  {
    id: "agpeya-midnight-1",
    title: { en: "Midnight — First Watch", ar: "نصف الليل — الخدمة الأولى" },
    blocks: [
      { kind: 'note', text: { en: "We pray the Midnight Prayer commemorating the Second Coming of our Lord and the resurrection of the dead. We watch and pray as we await the Bridegroom.", ar: "رُتِّبَت في مناسبة الصلوات الثلاث لفادينا في بستان جثسيماني. وكما يقول النبي في المزمور : في نصف الليل نهضت لأشكرك على أحكام عدلك." } },
      { kind: 'prayer', text: { en: "In the Name of the Father, and the Son, and the Holy Spirit, one God. Amen.", ar: "باسم الآب والابن والروح القدس" } },
      { kind: 'prayer', text: { en: "Kyrie eleison. Lord have mercy, Lord have mercy, Lord bless us. Amen.", ar: "الإله الواحد آمين." } },
      { kind: 'prayer', text: { en: "Glory be to the Father, and to the Son, and to the Holy Spirit, now and forever and unto the ages of ages. Amen.", ar: "يا رب ارحم. يا رب ارحم. يا رب بارك. آمين." } },
      { kind: 'prayer', text: { en: "", ar: "المجد للآب والابن والروح القدس الآن وكل أوان وإلى دهر الدهور آمين." } },
      { kind: 'prayer', text: { en: "", ar: "اللهم اجعلنا مستحقين أن نقول بشكر:" } },
      { kind: 'prayer', text: { en: "", ar: "أبانا الذي في السموات. ليتقدس اسمك. ليأت ملكوتك. لتكن مشيئتك. كما في السماء كذلك على الأرض. خبزنا الذي للغد أعطنا اليوم. وأغفر لنا ذنوبنا كما نغفر نحن أيضا للمذنبين إلينا. ولا تدخلنا في تجربة. لكن نجنا من الشرير. بالمسيح يسوع ربنا لأن لك الملك والقوة والمجد إلى الأبد. آمين." } },
      { kind: 'heading', text: { en: "Thanksgiving Prayer", ar: "صلاة الشكر" } },
      { kind: 'prayer', text: { en: "Let us give thanks to the beneficent and merciful God, the Father of our Lord, God and Savior, Jesus Christ, for He has covered us, helped us, guarded us, accepted us to Him, had compassion on us, supported us, and has brought us to this hour. Let us also ask Him, the Lord our God, the Pantocrator, to guard us in all peace this holy day and all the days of our life.", ar: "فلنشكر صانع الخيرات الرحوم الله، أبا ربنا وإلهنا ومخلصنا يسوع المسيح، لأنه سترنا وأعاننا، وحفظنا، وقبلنا إليه وأشفق علينا وعضدنا، وأتى بنا إلى هذه الساعة. هو أيضا فلنسأله أن يحفظنا في هذا اليوم المقدس وكل أيام حياتنا بكل سلام. الضابط الكل الرب إلهنا." } },
      { kind: 'prayer', text: { en: "O Master, Lord, God the Pantocrator, the Father of our Lord, God, and Savior, Jesus Christ, we thank You for every condition, concerning every condition, and in every condition. For You have covered us, helped us, guarded us, accepted us to You, had compassion on us, supported us, and brought us to this hour.", ar: "أيها السيد الإله ضابط الكل أبو ربنا وإلهنا ومخلصنا يسوع المسيح، نشكرك على كل حال ومن أجل كل حال، وفى كل حال، لأنك سترتنا، وأعنتنا، وحفظتنا، وقبلتنا إليك، وأشفقت علينا، وعضدتنا، وأتيت بنا إلى هذه الساعة." } },
      { kind: 'prayer', text: { en: "Therefore, we ask and entreat Your goodness, O Lover of Mankind. Grant us to complete this holy day, and all the days of our life, in all peace in Your fear. All envy, all temptation, all the work of Satan, the counsel of wicked men and the rising up of enemies, hidden and manifest, take them away from us and from all Your people and from this holy place that is Yours. But those things which are good and profitable do provide for us. For it is You who have given us the authority to trample on serpents and scorpions, and upon all the power of the enemy.", ar: "من أجل هذا نسأل ونطلب من صلاحك يا محب البشر، امنحنا أن نكمل هذا اليوم المقدس وكل أيام حياتنا بكل سلام مع خوفك. كل حسد، وكل تجربة وكل فعل الشيطان ومؤامرة الناس الأشرار، وقيام الأعداء الخفيين والظاهريين، انزعها عنا وعن سائر شعبك، وعن موضعك المقدس هذا. أما الصالحات والنافعات فارزقنا إياها. لأنك أنت الذي أعطيتنا السلطان أن ندوس الحيات والعقارب وكل قوة العدو. ولا تدخلنا في تجربة، لكن نجنا من الشرير." } },
      { kind: 'prayer', text: { en: "And lead us not into temptation, but deliver us from the evil one, by the grace, compassion and love-of-mankind, of Your only-begotten Son, our Lord, God and Savior, Jesus Christ. Through whom the glory, the honor, the dominion, and the adoration are due unto You, with Him, and the Holy Spirit, the Life-Giver, who is of one essence with You, now and at all times, and unto the age of all ages. Amen.", ar: "بالنعمة والرأفات ومحبة البشر اللواتي لابنك الوحيد ربنا وإلهنا ومخلصنا يسوع المسيح. هذا الذي من قبله المجد والإكرام والعزة والسجود تليق بك معه مع الروح القدس المحيي المساوي لك الآن وكل أوان وإلى دهر الدهور آمين." } },
      { kind: 'rubric', text: { en: "From the Psalms of our father David the prophet and king, may his blessings be upon us all. Amen.", ar: "تسبحة الخدمة الأولى من نصف الليل المبارك، أقدمها للمسيح ملكي والهي، وأرجوه أن يغفر لي خطاياي." } },
      { kind: 'heading', text: { en: "Psalm 50", ar: "مزمور" } },
      { kind: 'heading', text: { en: "Psalm 3", ar: "مزمور 3" } },
      { kind: 'psalm', text: { en: "O Lord, why have they who afflict me multiplied? Many have risen up upon me.", ar: "يا رب لماذا كثر الذين يحزنونني، كثيرون قاموا علي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Many say unto my soul, \"There is no salvation for him in his God.\"", ar: "كثيرون يقولون لنفسي، ليس له خلاص بإلهه." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "But You, O Lord, are my supporter, my glory, and the elevation of my head.", ar: "أنت يا رب أنت هو ناصري، مجدي ورافع رأسي." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "With my voice I cried unto the Lord.", ar: "بصوتي إلى الرب صرخت." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "And He heard me out of His holy mountain.", ar: "فاستجاب لي من جبل قدسه." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "I laid down and slept; and I arose; for the Lord is He who supports me.", ar: "أنا اضطجعت ونمت، ثم استيقظت لأن الرب ناصري." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "I will not be afraid of ten thousands of people, who surround me; who have risen upon me.", ar: "فلا أخاف من ربوات الجموع المحيطين بي القائمين على." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "Rise, O Lord, save me, O my God: for You have smitten all who are enemies to me without cause.", ar: "قم يا رب خلصني يا إلهي، لأنك ضربت كل من يعاديني باطلا." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "The teeth of the sinners You have broken.", ar: "أسنان الخطاة سحقتها." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "Salvation is the Lord's, and His blessing is upon His people.", ar: "للرب الخلاص وعلى شعبه بركته." }, label: { en: "10", ar: "10" } },
      { kind: 'heading', text: { en: "Psalm 6", ar: "مزمور 6" } },
      { kind: 'psalm', text: { en: "O Lord, do not rebuke me in Your anger, nor chasten me in Your wrath.", ar: "يا رب لا تبكتني بغضبك، ولا تؤدبني بسخطك." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Have mercy on me, O Lord; for I am weak: heal me, O Lord, for my bones are troubled, and my soul is grievously troubled.", ar: "ارحمني يا رب فإني ضعيف، اشفني يا رب فإن عظامي قد اضطربت ونفسي قد انزعجت جدا." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "But You, O Lord, how long? Return, deliver my soul: revive me for the sake of Your mercy.", ar: "وأنت يا رب فإلي متى؟ عد ونج نفسي، وأحيني من أجل رحمتك." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "For in death there is no one who is remembering You: and in Hades who is able to confess to You?", ar: "لأنه ليس في الموت من يذكرك ولا في الجحيم من يعترف لك." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "I became wearied in my groaning.", ar: "تعبت في تنهدي." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "I shall wash my bed every night; I shall wet my couch with my tears.", ar: "أعوم كل ليلة سريري، وبدموعي أبل فراشي." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "My eye is troubled because of anger.", ar: "تعكرت من الغضب عيناي." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "I have grown old because of all my enemies.", ar: "شاخت من سائر أعدائي ." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "Depart away from me, all who do iniquity.", ar: "ابعدوا عنى يا جميع فاعلي الإثم." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "For the Lord has heard the voice of my weeping.", ar: "لأن الرب قد سمع صوت بكائي." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "The Lord has heard my petition; the Lord has accepted my prayer. All my enemies shall be put to shame and greatly troubled: they shall be turned back and put to shame speedily.", ar: "الرب سمع تضرعي، الرب لصلاتي قبل، فليَخزَ وليضطرب جدا جميع أعدائي، وليرتدوا إلى ورائهم بالخزي سريعا جدا." }, label: { en: "11", ar: "11" } },
      { kind: 'heading', text: { en: "Psalm 12", ar: "مزمور 12" } },
      { kind: 'psalm', text: { en: "How long, O Lord, do You forget me, for ever? How long do You turn Your face away from me? How long do I put these counsels in my soul, and these sorrows in my heart for the whole day? How long does my enemy exalt over me? Look, hearken to me, O Lord my God.", ar: "إلى متى يا رب تنساني؟ إلى الانقضاء؟ حتى متى تصرف وجهك عنى؟ إلى متى أردد هذه المشورات في نفسي، وهذه الأوجاع في قلبي النهار كله؟ إلى متى يرتفع عدوى علي؟ انظر واستجب لي يا ربي وإلهي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Enlighten my eyes, lest I sleep in death; lest my enemy say, \"I have prevailed against him.\"", ar: "أنر عيني لئلا أنام نوم الموت، لئلا يقول عدوي: إني قد قويت عليه." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Those who distress me will rejoice if ever I stumble.", ar: "الذين يحزنونني يتهللون إن أنا زللت." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "But I have hoped in Your mercy.", ar: "أما أنا فعلى رحمتك توكلت." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "My heart will rejoice in Your salvation.", ar: "يبتهج قلبي بخلاصك." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "I will praise the Lord Who has done good to me, and I will sing to the name of the Lord Most High.", ar: "أسبح الرب المحسنَ إلي، وأرتل لاسم الرب العلي." }, label: { en: "6", ar: "6" } },
      { kind: 'heading', text: { en: "Psalm 69", ar: "مزمور 69" } },
      { kind: 'psalm', text: { en: "O God, be mindful of my help; make haste, O Lord, to help me.", ar: "اللهم التفت إلى معونتي، يا رب أسرع وأعنى." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Let them be ashamed and be scorned, those who seek my soul: let them be turned backward and put to shame, those who wish to do evil unto me.", ar: "ليَخزَ ويخجل طالبو نفسي، وليرتد إلى خلف ويخجل الذين يبتغون لي الشر." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Let those who say to me, \"Aha, aha,\" be turned back in shame immediately.", ar: "وليرجع بالخزي سريعا القائلون لي: نِعِمَّا نِعِمَّا." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Let all who seek You exult and be glad in You: and let those who love Your salvation say continually, \"Let the Lord be magnified.\"", ar: "وليبتهج ويفرح بك جميع الذين يلتمسونك، وليقل في كل حين محبو خلاصك: فليتعظم الرب." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "But I am poor and weak; O God, help me.", ar: "وأما أنا فمسكين وفقير، اللهم أعنى." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "You are my Helper and Savior, O Lord, do not delay. Alleluia.", ar: "أنت معيني ومخلصي يا رب فلا تبطئ.هلليلويا." }, label: { en: "6", ar: "6" } },
      { kind: 'heading', text: { en: "Psalm 85", ar: "مزمور 85" } },
      { kind: 'psalm', text: { en: "Incline Your ear, O Lord, and hear me; for I am poor and weak.", ar: "أمل يا رب أذنك واستمعني، لأني مسكين وبائس أنا." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Preserve my soul, for I am pure; save Your servant, O my God, who hopes in You.", ar: "احفظ نفسي لأني بار، يا إلهي خلص عبدك المتكل عليك." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Have mercy on me, O Lord: for to You I will cry the whole day.", ar: "ارحمني يا رب، لأني إليك أصرخ اليوم كله." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Rejoice the soul of Your servant: for to You, O Lord, I have lifted up my soul.", ar: "فرح نفس عبدك، لأني إليك يا رب رفعت نفسي." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "For You, O Lord, are righteous, and gentle; and plenteous is Your mercy to all who call upon You.", ar: "لأنك أنت يا رب صالح ووديع، ورحمتك كثيرة لكافة المستغيثين بك." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Give ear to my prayer, O Lord; and attend to the voice of my supplication.", ar: "أنصت يا رب إلي صلاتي، وأصغ إلى صوت تضرعي." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "In the day of my trouble I cried to You: for You heard me.", ar: "في يوم شدتي إليك صرختُ فأجبتني." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "There is none like You, O Lord, among the gods; and there is none that is able to do Your works.", ar: "فليس لك شبيه في الآلهة يا رب، ولا من يصنع كأعمالك." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "All nations whom You have made shall come, and shall worship before You, O Lord; and shall glorify Your name.", ar: "كل الأمم الذين خلقتهم يأتون ويسجدون أمامك يا رب، ويمجدون اسمك." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "For You are great, and wondrous: You alone are the great God.", ar: "لأنك أنت عظيم وصانع العجائب، أنت وحدك الإله العظيم." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "Guide me, O Lord, in Your way, and I shall walk in Your truth: let my heart rejoice, that I may fear Your name.", ar: "اهدني يا رب إلى طريقك فأسلك في حقك، ليفرح قلبي عند خوفه من اسمك." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "I will confess You, O Lord my God, with all my heart; and I will glorify Your name forever.", ar: "أعترف لك أيها الرب إلهي من كل قلبي، وأمجد اسمك إلى الأبد." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "For Your mercy is great toward me; and You have delivered my soul from the lowest Hades.", ar: "لأن رحمتك عظيمة على، وقد نجيت نفسي من الجحيم السفلي." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "O God, transgressors have risen up against me, and an assembly of violent men have sought my soul; and have not, at first, set You before them.", ar: "اللهم إن مخالفي الناموس قد قاموا علىّ ومجمع الأعزاء طلبوا نفسي، ولم يسبقوا أن يجعلوك أمامهم." }, label: { en: "14", ar: "14" } },
      { kind: 'psalm', text: { en: "But You, O Lord God, are compassionate and merciful.", ar: "وأنت أيها الرب الإله أنت رؤوف ورحيم." }, label: { en: "15", ar: "15" } },
      { kind: 'psalm', text: { en: "You are long-suffering, and abundant in mercy and true.", ar: "أنت طويل الروح، وكثير الرحمة وصادق." }, label: { en: "16", ar: "16" } },
      { kind: 'psalm', text: { en: "Look down upon me, and have mercy on me.", ar: "انظر إلي وارحمني." }, label: { en: "17", ar: "17" } },
      { kind: 'psalm', text: { en: "Give strength to Your servant, and save the son of Your handmaid.", ar: "أعطِ عزة لعبدك، وخلص ابن أمتك." }, label: { en: "18", ar: "18" } },
      { kind: 'psalm', text: { en: "Establish with me a sign for good; and let those who hate me see and be ashamed.", ar: "اصنع معي آية صالحة، ليرى ذلك مبغضي فيخزوا." }, label: { en: "19", ar: "19" } },
      { kind: 'psalm', text: { en: "Because You, O Lord, have helped me, and comforted me.", ar: "لأنك أنت يا رب أعنتني وعزيتني." }, label: { en: "20", ar: "20" } },
      { kind: 'heading', text: { en: "Psalm 90", ar: "مزمور 90" } },
      { kind: 'psalm', text: { en: "He who dwells in the help of the Most High, shall rest under the shelter of the God of heaven.", ar: "الساكن في عون العَليّ، يستريح في ظل إله السماء." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "He shall say to the Lord, \"You are my defender and my refuge: my God; I will hope in Him.\"", ar: "يقول للرب أنت هو ناصري وملجأي، إلهي فأتكل عليه." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "For He shall deliver you from the snare of the hunter, and from troublesome matter.", ar: "لأنه ينجيك من فخ الصياد، ومن كلمة مقلقة." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "He shall overshadow you in the midst of His shoulders, and you shall hope under His wings: His truth shall encompass you as a shield.", ar: "في وسط منكبيه يظللك، وتحت جناحيه تعتصم، عدله يحيط بك كالسلاح." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "You shall not be afraid of the terror of the night; nor of an arrow flying in the day.", ar: "فلا تخشى من خوف الليل، ولا من سهم يطير في النهار." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Nor of a matter walking in darkness; nor of calamity and demon of noon-day.", ar: "ولا من أمر يسلك في الظلمة، ولا من سقطة وشيطان الظهيرة." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "A thousand shall fall at your left hand, and ten thousand at your right hand; but they shall not be able to come near you.", ar: "يسقط عن يسارك ألوف، وعن يمينك ربوات، وأما أنت فلا يقتربون إليك." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "Only with your eyes shall you observe, and see the reward of sinners.", ar: "بل بعينيك تتأمل، ومجازاة الخطاة تبصر." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "For You, O Lord, are my hope.", ar: "لأنك أنت يا رب رجائي." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "You have made the Most High your refuge.", ar: "جعلتَ العليَّ ملجأك." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "No evil things shall come upon you, and no plague shall draw near to your dwelling.", ar: "فلا تصيبك الشرور، ولا تدنو ضربة من مسكنك." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "For He shall give His angels charge concerning you, to keep you in all your ways.", ar: "لأنه يوصى ملائكته بك، ليحفظوك في سائر طرقك." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "They shall bear you up on their hands, lest you stumble your foot against a stone.", ar: "وعلى أيديهم يحملونك، لئلا تعثر بحجر رجلك." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "You shall tread on the serpent and basilisk: and you shall trample on the lion and dragon.", ar: "تطأ الأفعى وملكَ الحيات، وتسحق الأسد والتنين." }, label: { en: "14", ar: "14" } },
      { kind: 'psalm', text: { en: "For he has hoped in Me, and I shall deliver him: I shall protect him, because he has known My name.", ar: "لأنه على أتكل فأنجيه، أرَفعه (أستره) لأنه عرف اسمي." }, label: { en: "15", ar: "15" } },
      { kind: 'psalm', text: { en: "He shall beseech Me, and I shall hear him.", ar: "يدعوني فأستجيب له." }, label: { en: "16", ar: "16" } },
      { kind: 'psalm', text: { en: "I am with him in affliction; and I shall deliver him, and glorify him.", ar: "معه أنا في الشدة، أنقذه وأمجده." }, label: { en: "17", ar: "17" } },
      { kind: 'psalm', text: { en: "I shall satisfy him with length of days, and show him My salvation.", ar: "ومن طول الأيام أشبعه، وأريه خلاصي." }, label: { en: "18", ar: "18" } },
      { kind: 'heading', text: { en: "Psalm 116", ar: "مزمور 116" } },
      { kind: 'psalm', text: { en: "Praise the Lord, all you nations: let all the peoples praise Him.", ar: "سبحوا الربَّ يا جميع الأمم ولتباركه كافة الشعوب." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "For His mercy has been established upon us, and the truth of the Lord endures forever. Alleluia.", ar: "لأن رحمته قد ثبتت علينا وحق الرب يدوم إلى الأبد هلليلويا." }, label: { en: "2", ar: "2" } },
      { kind: 'heading', text: { en: "Psalm 117", ar: "مزمور 117" } },
      { kind: 'psalm', text: { en: "Give thanks to the Lord; for He is good: for His mercy endures forever.", ar: "اعترفوا للرب لأنه صالح وأن إلى الأبد رحمته." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Let now the house of Israel say that He is good: for His mercy endures forever.", ar: "ليقل بيت إسرائيل إنه صالح وإن إلى الأبد رحمته." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Let the house of Aaron say that He is good: for His mercy endures forever.", ar: "ليقل بيت هارون إنه صالح وإن إلى الأبد رحمته." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Let now all who fear the Lord say that He is good: for His mercy endures forever.", ar: "ليقل أتقياء الرب إنه صالح وإن إلى الأبد رحمته." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "I called on the Lord in my affliction: and He answered me, and brought me into a broad place.", ar: "في ضيقتي صرختُ إلى الرب، فاستجاب لي وأخرجني إلى الرحب." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "The Lord is my helper; and I shall not fear what man will do to me.", ar: "الرب عوني فلا أخشى ماذا يصنع بي الإنسان." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "The Lord is my helper; and I shall look down upon my own enemies.", ar: "الرب لي معين وأنا أرى بأعدائي." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "It is better to trust in the Lord than to trust in man. It is better to hope in the Lord, than to hope in princes.", ar: "الاتكال على الرب خير من الاتكال على البشر، الرجاء بالرب خير من الرجاء بالرؤساء." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "All the nations surrounded me: and in the name of the Lord I drove them away.", ar: "كل الأمم أحاطوا بي وباسم الرب انتقمتُ منهم." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "They surrounded me and went around me: and in the name of the Lord I drove them away.", ar: "أحاطوا بي احتياطا واكتنفوني، وباسم الرب قهرتهم." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "They surrounded me as bees around a honeycomb, and they burst as fire among thorns: and in the name of the Lord I drove them away.", ar: "أحاطوا بي مثل النحل حول الشهد، والتهبوا كنار في شوك، وباسم الرب انتقمت منهم." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "I was pushed, that I might fall: but the Lord helped me.", ar: "دفعتُ لأسقطَ والرب عضدني." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "My strength and my praise is the Lord, and He has become unto me a salvation.", ar: "قوتي وتسبحتي هو الرب وقد صار لي خلاصا." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "The voice of exultation and salvation is in the dwellings of the righteous.", ar: "صوت التهليل والخلاص في مساكن الأبرار." }, label: { en: "14", ar: "14" } },
      { kind: 'psalm', text: { en: "The right hand of the Lord has wrought mightily. The right hand of the Lord has exalted me: the right hand of the Lord has wrought powerfully.", ar: "يمين الرب صنعت قوة، يمين الرب رفعتني، يمين الرب صنعت قوة." }, label: { en: "15", ar: "15" } },
      { kind: 'psalm', text: { en: "I shall not die, but live, and recount the works of the Lord.", ar: "فلن أموتَ بعدُ، بل أحيا وأحدث بأعمال الرب." }, label: { en: "16", ar: "16" } },
      { kind: 'psalm', text: { en: "With chastisement the Lord has chastened me: and has not given me up to death.", ar: "تأديبا أدبني الرب وإلى الموت لم يُسْلِمْني." }, label: { en: "17", ar: "17" } },
      { kind: 'psalm', text: { en: "Open to me the gates of righteousness: that I will go into them, and praise the Lord.", ar: "افتحوا لي أبواب البر لكي أدخل فيها وأعترفَ للرب." }, label: { en: "18", ar: "18" } },
      { kind: 'psalm', text: { en: "This is the gate of the Lord: the righteous shall enter into it.", ar: "هذا هو باب الرب والصديقون يدخلون فيه." }, label: { en: "19", ar: "19" } },
      { kind: 'psalm', text: { en: "I will praise You, O Lord, because You have answered me, and have become unto me a salvation.", ar: "أعترف لك يا رب لأنك استجبت لي وكنت لي مخلصا." }, label: { en: "20", ar: "20" } },
      { kind: 'psalm', text: { en: "The stone which the builders rejected has become the head of the corner.", ar: "الحجر الذي رذله البناءون هذا صار رأسا للزاوية." }, label: { en: "21", ar: "21" } },
      { kind: 'psalm', text: { en: "This has been done by the Lord; and it is wonderful in our eyes.", ar: "من قبل الرب كان هذا وهو عجيب في أعيننا." }, label: { en: "22", ar: "22" } },
      { kind: 'psalm', text: { en: "This is the day which the Lord has made.", ar: "هذا هو اليوم الذي صنعه الرب." }, label: { en: "23", ar: "23" } },
      { kind: 'psalm', text: { en: "Let us rejoice and be glad in it.", ar: "فلنبتهج ونفرح فيه." }, label: { en: "24", ar: "24" } },
      { kind: 'psalm', text: { en: "O Lord, save us.", ar: "يا رب خلصنا." }, label: { en: "25", ar: "25" } },
      { kind: 'psalm', text: { en: "O Lord, ease our ways.", ar: "يا رب سهل طريقنا." }, label: { en: "26", ar: "26" } },
      { kind: 'psalm', text: { en: "Blessed is He who comes in the name of the Lord.", ar: "مبارك الآتي باسم الرب." }, label: { en: "27", ar: "27" } },
      { kind: 'psalm', text: { en: "We have blessed you from the house of the Lord.", ar: "باركناكم من بيت الرب." }, label: { en: "28", ar: "28" } },
      { kind: 'psalm', text: { en: "God the Lord has shined upon us.", ar: "الله الرب أضاء علينا." }, label: { en: "29", ar: "29" } },
      { kind: 'psalm', text: { en: "Ordain a feast with those that reach the horns of the altar.", ar: "رتبوا عيدا في الواصلين إلى قرون المذبح." }, label: { en: "30", ar: "30" } },
      { kind: 'psalm', text: { en: "You are my God, and I will give thanks to You: You are my God, and I will exalt You.", ar: "أنت هو إلهي فأشكرك، إلهي أنت فأرفعك." }, label: { en: "31", ar: "31" } },
      { kind: 'psalm', text: { en: "I will give thanks to You, O Lord, for You have heard me, and have become unto me a salvation.", ar: "أعترف لك يا رب، لأنك استجبت لي وصرت لي مخلصا." }, label: { en: "32", ar: "32" } },
      { kind: 'psalm', text: { en: "Give thanks to the Lord; for He is good: for His mercy endures forever. Alleluia.", ar: "اشكروا الرب فإنه صالح وأن إلى الأبد رحمته هلليلويا" }, label: { en: "33", ar: "33" } },
      { kind: 'heading', text: { en: "Psalm 118", ar: "مزمور 118" } },
      { kind: 'psalm', text: { en: "Blessed are the blameless in the way, who walk in the law of the Lord.", ar: "طوباهم الذين بلا عيب في الطريق، السالكون في ناموس الرب." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Blessed are they who search out His testimonies: seeking Him with their whole heart.", ar: "طوباهم الذين يفحصون عن شهاداته، ومن قلوبهم يطلبونه،" }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "For they who work iniquity have not desired to walk in His ways.", ar: "لأن صانعي الإثم لم يهووا أن يسلكوا في سبله." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "You have commanded that Your commandments be diligently kept.", ar: "أنت أمرت أن تحفظ وصاياك جدا،" }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "O that my ways were directed to keep Your ordinances!", ar: "فيا ليت طرقي تستقيم إلى حفظ حقوقك." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Then I shall not be ashamed, when I look on all Your commandments.", ar: "حينئذ لا أخزى إذا ما اطلعت على جميع وصاياك." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "I will give thanks to You, O Lord, with uprightness of my heart, when I have learned the judgments of Your righteousness.", ar: "أشكرك يا رب باستقامة قلبي، إذ عرفت أحكام عدلك." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "I will keep Your ordinances: do not exceedingly forsake me!", ar: "حقوقك أحفظ، فلا ترفضني إلى الغاية." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "Wherewith shall a young man straighten his way? by keeping Your words.", ar: "بماذا يقوم الشاب طريقه؟ بحفظه أقوالك." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "With my whole heart I have sought You: do not cast me away from Your commandments.", ar: "من كل قلبي طلبتك،" }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "I have hidden Your words in my heart, that I might not sin against You.", ar: "فلا تبعدني عن وصاياك أخفيت أقوالك في قلبي لكي لا أخطئ إليك." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "Blessed are You, O Lord: teach me Your ordinances.", ar: "مبارك أنت يا رب علمني حقوقك." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "With my lips I have declared all the judgments of Your mouth.", ar: "بشفتي أظهرت كل أحكام فمك،" }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "I have delighted in the way of Your testimonies, as much as in all richness.", ar: "وفرحت بطريق شهاداتك كما بكل غنى." }, label: { en: "14", ar: "14" } },
      { kind: 'psalm', text: { en: "I shall speak of Your commandments, and consider Your ways.", ar: "بوصاياك أتكلم وأتفهم في طرقك،" }, label: { en: "15", ar: "15" } },
      { kind: 'psalm', text: { en: "I will meditate on Your ordinances, and I shall not forget Your words.", ar: "بفرائضك ألهج، ولا أنسى كلامك." }, label: { en: "16", ar: "16" } },
      { kind: 'psalm', text: { en: "Render a reward to Your servant: so I shall live, and keep Your words.", ar: "كافئ عبدك فأحيا وأحفظ أقوالك." }, label: { en: "17", ar: "17" } },
      { kind: 'psalm', text: { en: "Unveil my eyes, and I shall perceive wondrous things out of Your law.", ar: "اكشف عن عيني فـأرى عجائب من ناموسك." }, label: { en: "18", ar: "18" } },
      { kind: 'psalm', text: { en: "I am a stranger upon the earth: do not hide Your commandments from me.", ar: "غريب أنا في الأرض فلا تخفِ عنى وصاياك." }, label: { en: "19", ar: "19" } },
      { kind: 'psalm', text: { en: "My soul has longed to desire Your judgments at all times.", ar: "اشتاقت نفسي إلى اشتهاء أحكامك في كل حين." }, label: { en: "20", ar: "20" } },
      { kind: 'psalm', text: { en: "You have rebuked the proud: cursed are those who turn aside from Your commandments.", ar: "إنك انتهرت المتكبرين الملاعين الذين حادوا عن وصاياك." }, label: { en: "21", ar: "21" } },
      { kind: 'psalm', text: { en: "Remove from me the reproach and the contempt; for I have sought out Your testimonies.", ar: "انزع عنى العار والخزي فإني لشهاداتك ابتغيتُ." }, label: { en: "22", ar: "22" } },
      { kind: 'psalm', text: { en: "For princes sat and spoke against me: but Your servant was meditating on Your ordinances.", ar: "جلس الرؤساء وتقاولوا على، أما عبدك فكان يهتمُ بحقوقك،" }, label: { en: "23", ar: "23" } },
      { kind: 'psalm', text: { en: "For Your testimonies are my meditation, and Your ordinances are my counsels.", ar: "لأن شهاداتك هي درسي وحقوقك هي مشورتي" }, label: { en: "24", ar: "24" } },
      { kind: 'psalm', text: { en: "My soul has cleaved to the ground; revive me according to Your word.", ar: "لصقت بالتراب نفسي فأحيني ككلمتك." }, label: { en: "25", ar: "25" } },
      { kind: 'psalm', text: { en: "I declared Your ways, and You heard me: teach me Your ordinances.", ar: "أخبرت بطرقك فاستجب لي. علمني حقوقك،" }, label: { en: "26", ar: "26" } },
      { kind: 'psalm', text: { en: "Instruct me in Your ordinances, and make known to me the way of Your righteousness; and I will meditate on Your wondrous works.", ar: "وطريق عدلك فهمني، فألهج في عجائبك." }, label: { en: "27", ar: "27" } },
      { kind: 'psalm', text: { en: "My soul has slumbered from sorrow; strengthen me with Your words.", ar: "ذبلت نفسي من الحزن، فثبتني في أقوالك." }, label: { en: "28", ar: "28" } },
      { kind: 'psalm', text: { en: "Remove from me the way of iniquity; and be merciful to me by Your law.", ar: "طريق الظلم أبعد عنى وبناموسك ارحمني." }, label: { en: "29", ar: "29" } },
      { kind: 'psalm', text: { en: "I have chosen the way of truth; and have not forgotten Your judgments.", ar: "إني اخترت طريق الحق وأحكامك لم أنس." }, label: { en: "30", ar: "30" } },
      { kind: 'psalm', text: { en: "I have cleaved to Your testimonies, O Lord; do not put me to shame.", ar: "لصقتُ بشهاداتك يا رب فلا تخزني." }, label: { en: "31", ar: "31" } },
      { kind: 'psalm', text: { en: "I ran the way of Your commandments, when You enlarged my heart.", ar: "في طريق وصاياك سعيتُ عندما وسعتَ قلبي" }, label: { en: "32", ar: "32" } },
      { kind: 'psalm', text: { en: "Set before me, O Lord, a law in the way of Your ordinances, and I will seek it out every time.", ar: "ضع لي يا رب ناموسا في طريق حقوقك فأتبعَه كل حين." }, label: { en: "33", ar: "33" } },
      { kind: 'psalm', text: { en: "Give me understanding, and I shall search out Your law, and shall keep it with my whole heart.", ar: "فهمني فأبحث عن ناموسك وأحفظه بكل قلبي." }, label: { en: "34", ar: "34" } },
      { kind: 'psalm', text: { en: "Guide me in the path of Your commandments; for in this I have delighted.", ar: "اهدني في سبيل وصاياك فإني إياها هويت." }, label: { en: "35", ar: "35" } },
      { kind: 'psalm', text: { en: "Incline my heart to Your testimonies, and not to covetousness.", ar: "أمل قلبي إلى شهاداتك لا إلى الظلم." }, label: { en: "36", ar: "36" } },
      { kind: 'psalm', text: { en: "Turn away my eyes that I may not behold vanity: revive me in Your ways.", ar: "اردد عيني لئلا تعاينا الأباطيل، وفى سبلك أحيني." }, label: { en: "37", ar: "37" } },
      { kind: 'psalm', text: { en: "Set Your word with Your servant in Your fear.", ar: "ثبت قولك لعبدك في خوفك،" }, label: { en: "38", ar: "38" } },
      { kind: 'psalm', text: { en: "Take away from me the reproach which I have feared: for Your judgments are sweet.", ar: "وانزع عنى العار الذي حَذِرْتُ منه، فإن أحكامك حلوة." }, label: { en: "39", ar: "39" } },
      { kind: 'psalm', text: { en: "Behold, I have desired Your commandments: revive me in Your righteousness.", ar: "هاأنذا قد اشتهيتُ وصاياك، فأحيني ببرك" }, label: { en: "40", ar: "40" } },
      { kind: 'psalm', text: { en: "Let Your mercy come upon me, O Lord; and Your salvation, according to Your word.", ar: "لتأت عليّ رحمتك يا رب وخلاصك كقولك." }, label: { en: "41", ar: "41" } },
      { kind: 'psalm', text: { en: "So I shall answer with a word those who reproach me: for I have trusted in Your words.", ar: "فأجيب معيري بكلمة. لأني اتكلت على أقوالك،" }, label: { en: "42", ar: "42" } },
      { kind: 'psalm', text: { en: "Do not take the word of truth exceedingly out of my mouth; for I have hoped in Your judgments.", ar: "لا تنزع من فمي قول الحق، لأني توكلت على أحكامك، واحفظ شريعتك في كل حين،" }, label: { en: "43", ar: "43" } },
      { kind: 'psalm', text: { en: "And I will keep Your law every time, forever and ever.", ar: "إلى الأبد والى مدى الدهر." }, label: { en: "44", ar: "44" } },
      { kind: 'psalm', text: { en: "I walked also at large: for I sought out Your commandments.", ar: "كنتُ أسلك في السعة لأني لوصاياك ابتغيتُ." }, label: { en: "45", ar: "45" } },
      { kind: 'psalm', text: { en: "And I spoke of Your testimonies before the kings, and was not ashamed.", ar: "وتكلمت بشهاداتك قدام الملوك ولم أخزَ." }, label: { en: "46", ar: "46" } },
      { kind: 'psalm', text: { en: "And I meditated on Your commandments, those which I loved exceedingly.", ar: "ولهجتُ بوصاياك التي أحببتُها جدا،" }, label: { en: "47", ar: "47" } },
      { kind: 'psalm', text: { en: "And I lifted up my hands up to Your commandments which I exceedingly loved; and I meditated upon Your ordinances.", ar: "ورفعت يدي إلى وصاياك التي وددتُها جدا. وتأملتُ فرائضك." }, label: { en: "48", ar: "48" } },
      { kind: 'psalm', text: { en: "Remember Your words to Your servant, in which You have made me hope.", ar: "اذكر لعبدك كلامك الذي جعلتني عليه أتكل." }, label: { en: "49", ar: "49" } },
      { kind: 'psalm', text: { en: "This has comforted me in my affliction: for Your word is that which has revived me.", ar: "هذا الذي عزاني في مذلتي. لأن قولك أحياني." }, label: { en: "50", ar: "50" } },
      { kind: 'psalm', text: { en: "The proud have transgressed exceedingly; but I did not incline away from Your law.", ar: "إن المتكبرين تجاوزوا الناموس إلى الغاية، أما أنا فعن ناموسك لم أمِل." }, label: { en: "51", ar: "51" } },
      { kind: 'psalm', text: { en: "I remembered Your judgments from the beginning, O Lord; and was comforted.", ar: "تذكرتُ أحكامك يا رب منذ الدهر فتعزيتُ." }, label: { en: "52", ar: "52" } },
      { kind: 'psalm', text: { en: "Despair took hold of me, because of the sinners who forsook Your law.", ar: "الكآبة ملكتني من أجل الخطاة الذين تركوا ناموسك." }, label: { en: "53", ar: "53" } },
      { kind: 'psalm', text: { en: "Your ordinances were songs for me in the place of my sojourning.", ar: "حقوقك كانت لي مزاميرَ في موضع غربتي." }, label: { en: "54", ar: "54" } },
      { kind: 'psalm', text: { en: "I remembered Your name, O Lord, in the night, and kept Your law.", ar: "ذكرتُ في الليل اسمك يا رب، وحفظت شريعتك." }, label: { en: "55", ar: "55" } },
      { kind: 'psalm', text: { en: "This came unto me, because I sought Your ordinances.", ar: "هذا صار لي لأني طلبت حقوقك." }, label: { en: "56", ar: "56" } },
      { kind: 'psalm', text: { en: "You are my portion, O Lord: I said that I would keep Your commandments.", ar: "نصيبي أنت يا رب فقلت أن أحفظ وصاياك." }, label: { en: "57", ar: "57" } },
      { kind: 'psalm', text: { en: "I entreated Your face with my whole heart: have mercy on me according to Your word.", ar: "ترضيت وجهك بكل قلبي، فارحمني كقولك." }, label: { en: "58", ar: "58" } },
      { kind: 'psalm', text: { en: "I meditated on Your ways, and turned my feet to Your testimonies.", ar: "لأني تفكرت في طرقك ورددت قدمي إلى شهاداتك." }, label: { en: "59", ar: "59" } },
      { kind: 'psalm', text: { en: "I prepared myself, and was not troubled, to keep Your commandments.", ar: "تهيأت ولم أتوانَ لحفظ وصاياك." }, label: { en: "60", ar: "60" } },
      { kind: 'psalm', text: { en: "The bonds of sinners entrapped me: but I did not forget Your law.", ar: "رباطات الخطاة التفت على، أما شريعتك فلم أنسَها." }, label: { en: "61", ar: "61" } },
      { kind: 'psalm', text: { en: "At midnight I usually arise, to give thanks to You for the judgments of Your righteousness.", ar: "في نصف الليل نهضت لأشكرك على أحكام عدلك." }, label: { en: "62", ar: "62" } },
      { kind: 'psalm', text: { en: "I am the companion of all who fear You, and of all who keep Your commandments.", ar: "شريك أنا لكل الذين يخافونك، وللحافظين وصاياك." }, label: { en: "63", ar: "63" } },
      { kind: 'psalm', text: { en: "O Lord, the earth is filled of Your mercy: teach me Your ordinances.", ar: "من رحمتك يا رب امتلأت الأرضُ فعلمني عدلك" }, label: { en: "64", ar: "64" } },
      { kind: 'psalm', text: { en: "You have done good with Your servant, O Lord, according to Your word.", ar: "خيرا صنعتَ مع عبدك يا رب حسب قولك،" }, label: { en: "65", ar: "65" } },
      { kind: 'psalm', text: { en: "Teach me kindness, and instruction, and knowledge: for I have believed Your commandments.", ar: "صلاحا وأدبا ومعرفة، علمني فإني قد صدقت وصاياك." }, label: { en: "66", ar: "66" } },
      { kind: 'psalm', text: { en: "Before I was humbled, I became lazy; therefore I have kept Your word.", ar: "قبل أن أتواضع أنا تكاسلتُ. فلهذا حفظتُ كلامك." }, label: { en: "67", ar: "67" } },
      { kind: 'psalm', text: { en: "Sweet are You, O Lord; and in Your goodness teach me Your ordinances.", ar: "صالح أنت يا رب فبصلاحك علمني حقوقك." }, label: { en: "68", ar: "68" } },
      { kind: 'psalm', text: { en: "The injustice of the proud has been multiplied against me: but I shall search out Your commandments with all my heart.", ar: "كثر عليّ ظلم المتكبرين، وأنا بكل قلبي أبحث عن وصاياك." }, label: { en: "69", ar: "69" } },
      { kind: 'psalm', text: { en: "Their heart has been curdled like milk; but I have meditated on Your law.", ar: "تجبن مثل اللبن قلبهم، وأنا لهجت بناموسك." }, label: { en: "70", ar: "70" } },
      { kind: 'psalm', text: { en: "It is good for me that You have humbled me; that I might learn Your ordinances.", ar: "خير لي أنك أذللتني حتى أتعلمَ حقوقك." }, label: { en: "71", ar: "71" } },
      { kind: 'psalm', text: { en: "The law of Your mouth is better to me than thousands of gold and silver.", ar: "ناموس فمك خير لي من ألوف ذهب وفضة" }, label: { en: "72", ar: "72" } },
      { kind: 'psalm', text: { en: "Your hands have made me, and fashioned me: instruct me, that I will learn Your commandments.", ar: "يداك صنعتاني وجبلتاني. فهمني فأتعلم وصاياك." }, label: { en: "73", ar: "73" } },
      { kind: 'psalm', text: { en: "They who fear You shall see me and rejoice: for I have hoped in Your words.", ar: "الذين يخافونك يبصرونني ويفرحون، لأني بكلامك وثقت." }, label: { en: "74", ar: "74" } },
      { kind: 'psalm', text: { en: "I know, O Lord, that Your judgments are righteousness, and that You truly have humbled me.", ar: "قد علمتُ يا رب أن أحكامك عادلة وبحق أذللتني." }, label: { en: "75", ar: "75" } },
      { kind: 'psalm', text: { en: "Let, Your mercy come upon me to comfort me, according to Your word to Your servant.", ar: "فلتأتِ عليّ رحمتك لتعزيني، نظير قولك لعبدك." }, label: { en: "76", ar: "76" } },
      { kind: 'psalm', text: { en: "Let Your compassion come to me, that I shall live: for Your law is my meditation.", ar: "لتأتني رأفتك فأحيا فإن ناموسك هو درسي." }, label: { en: "77", ar: "77" } },
      { kind: 'psalm', text: { en: "Let the proud be ashamed: for they transgressed against me unjustly: but I shall be continually in Your commandments.", ar: "وليخز المتكبرون لأنهم خالفوا الشرع عليّ ظلما، وأنا كنت مثابرا على وصاياك." }, label: { en: "78", ar: "78" } },
      { kind: 'psalm', text: { en: "Let those who fear You, and those who know Your wonders, turn to me.", ar: "وليرجع إليّ الذين يتقونك ويعرفون عجائبك،" }, label: { en: "79", ar: "79" } },
      { kind: 'psalm', text: { en: "Let my heart be blameless in Your ordinances, that I may not be ashamed.", ar: "وليصر قلبي بلا عيب في عدلك لكي لا أخزي" }, label: { en: "80", ar: "80" } },
      { kind: 'psalm', text: { en: "My soul has fainted for Your salvation: and I have hoped in Your words.", ar: "تاقت نفسي إلى خلاصك وعلى كلامك توكلت." }, label: { en: "81", ar: "81" } },
      { kind: 'psalm', text: { en: "My eyes failed in waiting for Your word, saying, \"When will You comfort me?\" I have become as a bottle in the frost: but I have not forgotten Your ordinances.", ar: "كلت عيناي من انتظار أقوالك قائلتين: متى تعزيني ؟" }, label: { en: "82", ar: "82" } },
      { kind: 'psalm', text: { en: "How many are the days of Your servant?", ar: "صرتُ مثل زق في جليد ولحقوقك لم أنس. كم هي أيام عبدك ؟" }, label: { en: "83", ar: "83" } },
      { kind: 'psalm', text: { en: "When will You execute judgment for me on those who persecute me?", ar: "متى تجري لي حكما على الذين يضطهدونني؟" }, label: { en: "84", ar: "84" } },
      { kind: 'psalm', text: { en: "Transgressors told me idle words; but not according to Your law, O Lord.", ar: "تكلم معي مخالفو الناموس بكلام هذيان، لكن ليس كناموسك يا رب،" }, label: { en: "85", ar: "85" } },
      { kind: 'psalm', text: { en: "For all Your commandments are truth; they persecuted me unjustly; help me.", ar: "لأن كل وصاياك هي حق." }, label: { en: "86", ar: "86" } },
      { kind: 'psalm', text: { en: "They nearly destroyed me upon the earth; but I did not forsake Your commandments.", ar: "وبظلم قد طردوني فأعني؟ كادوا يفنونني على الأرض، أما أنا فلم أترك وصاياك." }, label: { en: "87", ar: "87" } },
      { kind: 'psalm', text: { en: "Revive me according to Your mercy; so I shall keep the testimonies of Your mouth.", ar: "حسب رحمتك أحيني فأحفظ شهادات فمك" }, label: { en: "88", ar: "88" } },
      { kind: 'psalm', text: { en: "Your word, O Lord, abides in the heavens forever.", ar: "يا رب كلمتك دائمة في السموات إلى الأبد، وإلى جيل فجيل حقك." }, label: { en: "89", ar: "89" } },
      { kind: 'psalm', text: { en: "Your truth endures from generation to generation; You have founded the earth, and it abides by Your command.", ar: "أسست الأرض فهي ثابتة بأمرك، والنهار أيضا ثابت." }, label: { en: "90", ar: "90" } },
      { kind: 'psalm', text: { en: "The day also abides; for all things are Your servants.", ar: "لأن كل الأشياء متعبدة لك." }, label: { en: "91", ar: "91" } },
      { kind: 'psalm', text: { en: "Were it not that Your law was my meditation, I would have perished in my humility.", ar: "لو لم تكن شريعتك تلاوتي لهلكتُ حينئذ في مذلتي." }, label: { en: "92", ar: "92" } },
      { kind: 'psalm', text: { en: "I shall never forget Your ordinances; for with them You have revived me.", ar: "وإلى الدهر لا أنسى وصاياك لأنك بها أحييتني يا رب." }, label: { en: "93", ar: "93" } },
      { kind: 'psalm', text: { en: "I am Yours, save me; for I have sought out Your ordinances.", ar: "لك أنا فخلصني يا رب، لأني لوصاياك طلبتُ." }, label: { en: "94", ar: "94" } },
      { kind: 'psalm', text: { en: "The sinners have waited for me to destroy me; but I understood Your testimonies.", ar: "إياي انتظر الخطاة ليهلكوني، ولشهاداتك فهمت." }, label: { en: "95", ar: "95" } },
      { kind: 'psalm', text: { en: "I have seen an end of every perfection; but Your commandments are very broad.", ar: "لكل تمام رأيت منتهى أما وصاياك فواسعة جدا" }, label: { en: "96", ar: "96" } },
      { kind: 'psalm', text: { en: "How beloved is Your name, O Lord! It is my meditation the whole day.", ar: "محبوب هو اسمك يا رب، فهو طولَ النهار تلاوتي." }, label: { en: "97", ar: "97" } },
      { kind: 'psalm', text: { en: "You have instructed me more than my enemies in Your commandments; for they are mine forever.", ar: "علمتني وصاياك أفضل من أعدائي، لأنها ثابتة لي إلى الأبد." }, label: { en: "98", ar: "98" } },
      { kind: 'psalm', text: { en: "I have more understanding than all who teach me; for Your testimonies are my meditation.", ar: "أكثر من جميع الذين يعلمونني فهمتُ، لأن شهادتك هي درسي." }, label: { en: "99", ar: "99" } },
      { kind: 'psalm', text: { en: "I understood more than the aged; because I sought out Your commandments.", ar: "أكثر من الشيوخ فهمتُ، لأني طلبتُ وصاياك." }, label: { en: "100", ar: "100" } },
      { kind: 'psalm', text: { en: "I have kept back my feet from every evil way, that I might keep Your words.", ar: "من كل طريق خبيث منعتُ رجليّ لكي أحفظ كلامك." }, label: { en: "101", ar: "101" } },
      { kind: 'psalm', text: { en: "I have not declined from Your judgments; for You have set a law for me.", ar: "عن كلامك لم أحد، لأنك وضعتَ لي ناموسا." }, label: { en: "102", ar: "102" } },
      { kind: 'psalm', text: { en: "How sweet are Your words to my throat, more so than honey and honey comb in my mouth!", ar: "إن كلماتك حلوة في حلقي، أفضل من العسل والشهد في فمي." }, label: { en: "103", ar: "103" } },
      { kind: 'psalm', text: { en: "I gain understanding from Your commandments: therefore I have hated every way of unrighteousness.", ar: "من وصاياك تفطنتُ، فلهذا أبغضت كل طرق الظلم. (لأنك وضعتَ لي ناموسًا)" }, label: { en: "104", ar: "104" } },
      { kind: 'psalm', text: { en: "Your law is a lamp to my feet, and a light to my paths.", ar: "مصباح لرجلي كلامك ونور لسبلي." }, label: { en: "105", ar: "105" } },
      { kind: 'psalm', text: { en: "I have sworn and determined to keep the judgments of Your righteousness.", ar: "حلفت فأقمت على حفظ أحكام عدلك." }, label: { en: "106", ar: "106" } },
      { kind: 'psalm', text: { en: "I have been greatly humbled, revive me, O Lord, according to Your word.", ar: "تذللت جدا إلى الغاية يا رب، أحيني كقولك." }, label: { en: "107", ar: "107" } },
      { kind: 'psalm', text: { en: "Bless, O Lord, the promises of my mouth, and teach me Your judgments.", ar: "تعهدات فمي باركها يا رب، وأحكامك علمني." }, label: { en: "108", ar: "108" } },
      { kind: 'psalm', text: { en: "My soul is continually in Your hands; and I have not forgotten Your law.", ar: "نفسي في يديك كل حين، وناموسك لم أنسَ،" }, label: { en: "109", ar: "109" } },
      { kind: 'psalm', text: { en: "The sinners hid a snare for me; and I did not stray from Your commandments.", ar: "أخفى الخطاة لي فخا، ولم أضل عن وصاياك." }, label: { en: "110", ar: "110" } },
      { kind: 'psalm', text: { en: "I have inherited Your testimonies forever; for they are the joy of my heart.", ar: "ورثت شهاداتك إلى الأبد، لأنها بهجة قلبي." }, label: { en: "111", ar: "111" } },
      { kind: 'psalm', text: { en: "I have inclined my heart to perform Your righteousness forever, for the sake of a reward.", ar: "عطفت قلبي لأصنع برك إلى الأبد (من أجل المكافأة)" }, label: { en: "112", ar: "112" } },
      { kind: 'psalm', text: { en: "I have hated transgressors; and I have loved Your law.", ar: "لمتجاوزي الناموس أبغضتُ ولناموسك أحببت." }, label: { en: "113", ar: "113" } },
      { kind: 'psalm', text: { en: "You are my helper and my supporter; I have hoped in Your word.", ar: "لأنك أنت معيني وناصري. وعلى كلامك توكلت." }, label: { en: "114", ar: "114" } },
      { kind: 'psalm', text: { en: "Turn away from me, you evil-doers; for I shall search out the commandments of my God.", ar: "ابعدوا عني أيها الأشرار فأفحص عن وصايا إلهي." }, label: { en: "115", ar: "115" } },
      { kind: 'psalm', text: { en: "Uphold me according to Your word, and I shall live; and do not make me ashamed of my hope.", ar: "عضدني حسب قولك فأحيا ولا تخيب رجائي." }, label: { en: "116", ar: "116" } },
      { kind: 'psalm', text: { en: "Help me, and I shall be saved; and I shall meditate on Your ordinances continually.", ar: "أعني فأخلص، وأدرس في وصاياك كل حين." }, label: { en: "117", ar: "117" } },
      { kind: 'psalm', text: { en: "You have brought to nought all who turn away from Your ordinances; for their thought is an iniquity.", ar: "رذلتَ سائر الذين حادوا عن وصاياك لأن فكرهم ظلم." }, label: { en: "118", ar: "118" } },
      { kind: 'psalm', text: { en: "I have reckoned all the sinners of the earth as transgressors; therefore I have loved Your testimonies at all times.", ar: "عصاة حسبتَ سائر خطاة الأرض، فلهذا أحببتُ شهاداتك في كل حين." }, label: { en: "119", ar: "119" } },
      { kind: 'psalm', text: { en: "Nail Your fear to my flesh; for I feared Your judgments.", ar: "سمر خوفك في لحمي لأني من أحكامك جزعتُ" }, label: { en: "120", ar: "120" } },
      { kind: 'psalm', text: { en: "I have done judgment and justice; do not deliver me to the hands of those who injure me.", ar: "قد أجريتُ حكما وعدلا فلا تسلمني إلى الذين يظلمونني." }, label: { en: "121", ar: "121" } },
      { kind: 'psalm', text: { en: "Accept Your servant unto You for good: do not let the proud say falsehood against me.", ar: "كن لعبدك كفيلا في الخير، لئلا يجوزَ عليّ المتكبرون." }, label: { en: "122", ar: "122" } },
      { kind: 'psalm', text: { en: "My eyes have failed for Your salvation, and for the word of Your righteousness.", ar: "عيناي قد ذبلتا من انتظار خلاصك وقول عدلك." }, label: { en: "123", ar: "123" } },
      { kind: 'psalm', text: { en: "Deal with Your servant according to Your mercy, and teach me Your ordinances.", ar: "اصنع مع عبدك حسب رحمتك، وحقوقك علمني." }, label: { en: "124", ar: "124" } },
      { kind: 'psalm', text: { en: "I am Your servant; instruct me, and I will know Your testimonies.", ar: "عبدك أنا، فهمني فأعرف شهاداتك." }, label: { en: "125", ar: "125" } },
      { kind: 'psalm', text: { en: "It is the time to work for the Lord: they have utterly broken Your law.", ar: "إنه وقتٌ يعمل فيه للرب، لأنهم قد نقضوا ناموسك." }, label: { en: "126", ar: "126" } },
      { kind: 'psalm', text: { en: "Therefore I have loved Your commandments more than gold and topaz.", ar: "لأجل هذا أحببتُ وصاياك أفضل من الذهب والجوهر،" }, label: { en: "127", ar: "127" } },
      { kind: 'psalm', text: { en: "Therefore I stood for all Your commandments: I have hated every unjust way.", ar: "ولأجل هذا بازاء كل وصاياك تقومتُ، وكل طريق ظلم أبغضتُ" }, label: { en: "128", ar: "128" } },
      { kind: 'psalm', text: { en: "Your testimonies are wonderful: therefore my soul has kept them.", ar: "عجيبة هي شهاداتك لذلك حفظتها نفسي." }, label: { en: "129", ar: "129" } },
      { kind: 'psalm', text: { en: "The manifestation of Your words shall enlighten, and instruct the small children.", ar: "إعلان أقوالك ينير لي، ويفهم الأطفال والصغار." }, label: { en: "130", ar: "130" } },
      { kind: 'psalm', text: { en: "I opened my mouth, and drew a spirit unto me: for I earnestly longed for Your commandments.", ar: "فتحت فهمي واجتذبتُ لي روحا، لأني لوصاياك اشتقتُ." }, label: { en: "131", ar: "131" } },
      { kind: 'psalm', text: { en: "Look upon me and have mercy on me, after the manner of those who love Your name.", ar: "انظر إليّ وارحمني كرحمتك للذين يحبون اسمك." }, label: { en: "132", ar: "132" } },
      { kind: 'psalm', text: { en: "Make straight my steps according to Your word: and let not any iniquity have dominion over me.", ar: "قوم خطواتي كقولك فلا يتسلط على أيُّ إثم." }, label: { en: "133", ar: "133" } },
      { kind: 'psalm', text: { en: "Deliver me from the false accusation of men: so I shall keep Your commandments.", ar: "أنقذني من ظلم الناس فأحفظ وصاياك." }, label: { en: "134", ar: "134" } },
      { kind: 'psalm', text: { en: "Let Your face shine upon Your servant: and teach me Your ordinances.", ar: "أضئ بوجهك على عبدك وعلمني حقوقك." }, label: { en: "135", ar: "135" } },
      { kind: 'psalm', text: { en: "My eyes have been bathed in the streams of waters, because they did not keep Your law.", ar: "غاصت عيناي في مجاري المياه، لأنهم لم يحفظوا ناموسك." }, label: { en: "136", ar: "136" } },
      { kind: 'psalm', text: { en: "Righteous are You, O Lord, and upright are Your judgments.", ar: "عادل أنت يا رب وقضاؤك مستقيم." }, label: { en: "137", ar: "137" } },
      { kind: 'psalm', text: { en: "You have commanded justice and truth exceedingly, which are Your testimonies.", ar: "أوصيتَ كثيرا بالعدل والحق اللذين هما شهاداتك." }, label: { en: "138", ar: "138" } },
      { kind: 'psalm', text: { en: "The zeal has eaten me up: because my enemies have forgotten Your commandments.", ar: "غيرة بيتك أكلتني، لأن أعدائي نسوا وصاياك." }, label: { en: "139", ar: "139" } },
      { kind: 'psalm', text: { en: "Your word has been very fully tried; and Your servant loves it.", ar: "ممحص قولك جدا، وعبدك أحبه." }, label: { en: "140", ar: "140" } },
      { kind: 'psalm', text: { en: "I am young and despised: yet I have not forgotten Your ordinances.", ar: "صغيرٌ أنا ومرذول وحقوقك لم أنسَ." }, label: { en: "141", ar: "141" } },
      { kind: 'psalm', text: { en: "Your righteousness is an everlasting righteousness, and Your word is truth.", ar: "عدلك حق هو إلى الأبد، وكلامك حق هو." }, label: { en: "142", ar: "142" } },
      { kind: 'psalm', text: { en: "Afflictions and distresses found me: but Your commandments are my meditation.", ar: "ضيق وشدة أدركاني، ووصاياك هي درسي." }, label: { en: "143", ar: "143" } },
      { kind: 'psalm', text: { en: "Your testimonies are righteousness forever: instruct me, and I shall live.", ar: "عادلة هي شهاداتك إلى الأبد. فهمني فأحيا" }, label: { en: "144", ar: "144" } },
      { kind: 'psalm', text: { en: "I cried with my whole heart; hear me, O Lord: I shall search out Your ordinances.", ar: "صرخت من كل قلبي، فاستجب لي يا رب. إني أبتغي حقوقك." }, label: { en: "145", ar: "145" } },
      { kind: 'psalm', text: { en: "I cried up to You; save me, and I shall keep Your testimonies.", ar: "صرختُ إليك فخلصني، لأحفظ شهاداتك." }, label: { en: "146", ar: "146" } },
      { kind: 'psalm', text: { en: "I hastened to arise before the time, and cried: and I hoped in Your word.", ar: "سبقتُ وقمتُ قبل الوقتِ وصرخت، وعلى كلامك توكلتُ." }, label: { en: "147", ar: "147" } },
      { kind: 'psalm', text: { en: "My eyes hastened to awake before the dawn, that I might meditate on Your words.", ar: "سبقتْ عيناي وقت السحَر، لأتلو في جميع أقوالك،" }, label: { en: "148", ar: "148" } },
      { kind: 'psalm', text: { en: "Hear my voice, O Lord, according to Your mercy; revive me according to Your judgments.", ar: "فاسمع صوتي يا رب كرحمتك، وبحسب أحكامك أحيني." }, label: { en: "149", ar: "149" } },
      { kind: 'psalm', text: { en: "They have drawn near who persecuted me in iniquity; and they are far removed from Your law.", ar: "اقترب بالإثم الذين يطردونني، وعن ناموسك ابتعدوا." }, label: { en: "150", ar: "150" } },
      { kind: 'psalm', text: { en: "You are near, O Lord; and all Your commandments are truth.", ar: "قريب أنت يا رب، وكل وصاياك حق هي." }, label: { en: "151", ar: "151" } },
      { kind: 'psalm', text: { en: "Since the beginning I knew from Your testimonies, that You had founded them forever.", ar: "منذ البدء عرفتُ من شهاداتك أنك إلى الدهر أسستها" }, label: { en: "152", ar: "152" } },
      { kind: 'psalm', text: { en: "Look upon my humiliation, and save me: for I have not forgotten Your law.", ar: "انظر إلى مذلتي وأنقذني، فإني لم أنس ناموسك. احكم لي في دعواي ونجني." }, label: { en: "153", ar: "153" } },
      { kind: 'psalm', text: { en: "Plead my cause, and redeem me: revive me for the sake of Your word.", ar: "من أجل كلامك أحيني." }, label: { en: "154", ar: "154" } },
      { kind: 'psalm', text: { en: "Salvation is far from sinners: for they have not searched out Your ordinances.", ar: "بعيد هو الخلاص عن الخطاة، لأنهم لم يطلبوا حقوقك." }, label: { en: "155", ar: "155" } },
      { kind: 'psalm', text: { en: "Your mercies, O Lord, are many: revive me according to Your judgments.", ar: "رأفتك كثيرة جدا يا رب. حسب أحكامك أحيني." }, label: { en: "156", ar: "156" } },
      { kind: 'psalm', text: { en: "Many are they who persecute me and distress me: but I did not turn away from Your testimonies.", ar: "كثيرون هُمُ الذين يضطهدونني ويحزنونني، وعن شهاداتك لم أجنح." }, label: { en: "157", ar: "157" } },
      { kind: 'psalm', text: { en: "I beheld foolish men, and I suffered; for they did not keep Your words.", ar: "رأيت الذين لا يفهمون فاكتأبت، لأنهم لأقوالك لم يحفظوا." }, label: { en: "158", ar: "158" } },
      { kind: 'psalm', text: { en: "Behold, O Lord, I have loved Your commandments: revive me in Your mercy.", ar: "انظر يا رب، فإني أحببت وصاياك. برحمتك يا رب أحيني." }, label: { en: "159", ar: "159" } },
      { kind: 'psalm', text: { en: "The beginning of Your words is truth; and all judgments of Your righteousness are forever.", ar: "بدء كلامك حقٌ، وإلي الأبد كل أحكام عدلك" }, label: { en: "160", ar: "160" } },
      { kind: 'psalm', text: { en: "Princes persecuted me without a cause, my heart was afraid of Your words.", ar: "الرؤساء اضطهدوني بلا سبب. من أقوالك جزع قلبي." }, label: { en: "161", ar: "161" } },
      { kind: 'psalm', text: { en: "I will exult because of Your words, as one who has found a great treasure.", ar: "أبتهج أنا بكلامك كمن وجد غنائمَ كثيرة." }, label: { en: "162", ar: "162" } },
      { kind: 'psalm', text: { en: "I hated and abhorred unrighteousness; but I loved Your law.", ar: "أبغضتُ الظلم ورذلته، أما ناموسك فأحببته." }, label: { en: "163", ar: "163" } },
      { kind: 'psalm', text: { en: "Seven times a day I have praised You because of the judgments of Your righteousness.", ar: "سبع مرات في النهار سبحتك على أحكام عدلك." }, label: { en: "164", ar: "164" } },
      { kind: 'psalm', text: { en: "Let great peace be for those who love Your law: and there is no stumbling in them.", ar: "فليكن سلام عظيم للذين يحبون اسمك، وليس لهم شك." }, label: { en: "165", ar: "165" } },
      { kind: 'psalm', text: { en: "I waited for Your salvation, O Lord, and have loved Your commandments.", ar: "توقعتُ خلاصك يا رب ووصاياك أحببتها." }, label: { en: "166", ar: "166" } },
      { kind: 'psalm', text: { en: "My soul has kept Your testimonies, and loved them exceedingly.", ar: "حفظتْ نفسي شهاداتك وأحببتها جدا." }, label: { en: "167", ar: "167" } },
      { kind: 'psalm', text: { en: "I have kept Your commandments and Your testimonies; and all my ways are before You, O Lord.", ar: "حفظتُ وصاياك وشهاداتك، وكل طرقي أمامك يا رب." }, label: { en: "168", ar: "168" } },
      { kind: 'psalm', text: { en: "Let my supplication come near before You; give me understanding according to Your word.", ar: "فلتدن وسيلتي قدامك يا رب، كقولك فهمني." }, label: { en: "169", ar: "169" } },
      { kind: 'psalm', text: { en: "Let my petition come before You, revive me according to Your word.", ar: "فلتدخل طلبتي إلى حضرتك يا رب، ككلمتك أحيني." }, label: { en: "170", ar: "170" } },
      { kind: 'psalm', text: { en: "Let my lips flow with praise, when You have taught me Your ordinances.", ar: "تفيض شفتاي السبح إذا ما علمتني حقوقك." }, label: { en: "171", ar: "171" } },
      { kind: 'psalm', text: { en: "Let my tongue speak of Your words; for all Your commandments are righteous.", ar: "لساني ينطق بأقوالك لأن جميع وصاياك عادلة." }, label: { en: "172", ar: "172" } },
      { kind: 'psalm', text: { en: "Let Your hand be for saving me; for I have desired Your commandments.", ar: "لتكن يدك لخلاصي لأنني اشتهيت وصاياك." }, label: { en: "173", ar: "173" } },
      { kind: 'psalm', text: { en: "I have longed for Your salvation, O Lord; and Your law is my meditation.", ar: "اشتقتُ إلى خلاصك يا رب، وناموسك هو تلاوتي." }, label: { en: "174", ar: "174" } },
      { kind: 'psalm', text: { en: "My soul shall live and praise You; and Your judgments shall help me.", ar: "تحيا نفسي وتسبحك، وأحكامك تعينيني." }, label: { en: "175", ar: "175" } },
      { kind: 'psalm', text: { en: "I have gone astray like a lost sheep; seek Your servant; for I have not forgotten Your commandments.", ar: "ضللت مثل الخروف الضال، فاطلب عبدك، فإني لوصاياك لم أنسَ." }, label: { en: "176", ar: "176" } },
      { kind: 'rubric', text: { en: "Glory to You, O our God. Holy, holy, holy. A reading from the Gospel according to our teacher Saint Matthew the Evangelist. May his blessings be with us all. Amen.", ar: "Glory to You, O our God. Holy, holy, holy. A reading from the Gospel according to our teacher Saint Matthew the Evangelist. May his blessings be with us all. Amen." } },
      { kind: 'gospel', text: { en: "Matthew 25:1-13", ar: "متى 25:1-13" }, label: { en: "Gospel", ar: "الإنجيل" } },
      { kind: 'litany', text: { en: "We worship You, O Christ, with Your Good Father and the Holy Spirit, for You have come and saved us. Lord have mercy.", ar: "ها هو ذا العريس يأتي في نصف الليل، طوبى للعبد الذي يجده مستيقظا. أما الذي يجده متغافلا، فإنه غير مستحق المضي معه. فانظري يا نفسي لئلا تثقلي نوما، فتلقي خارج الملكوت. بل اسهري واصرخي قائلة: قدوس قدوس قدوس أنت يا الله، من أجل والدة الإله ارحمنا (" } },
      { kind: 'litany', text: { en: "Behold, the Bridegroom comes at midnight, and blessed is that servant whom He shall find watching. Lord have mercy.", ar: "ذوكصابتري" } },
      { kind: 'litany', text: { en: "Make us worthy, O Lord, to watch with the wise virgins, awaiting Your coming with lamps trimmed and burning. Lord have mercy.", ar: "كيه إيو كي آجيو ابنيفماتي" } },
      { kind: 'litany', text: { en: "", ar: "المجد للآب والابن والروح القدس" } },
      { kind: 'litany', text: { en: "", ar: "تفهمي يا نفسي ذلك اليومَ الرهيب واستيقظي، وأضيئي مصباحك بزيت البهجة. لأنك لا تعلمين متى يأتي نحوك الصوت القائل: ها هو ذا العريس قد أقبل. فانظري يا نفسي لا تنعسي، لئلا تقفي خارجا قارعة مثل الخمس العذارى الجاهلات، بل اسهري متضرعة لكي تلتقي المسيح الرب بدهن دسم، وينعم عليك بعرس مجده الإلهي الحقيقي (كي نين" } },
      { kind: 'litany', text: { en: "", ar: "، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين" } },
      { kind: 'litany', text: { en: "", ar: "الآن وكل أوان وإلى دهر الداهرين آمين" } },
      { kind: 'litany', text: { en: "", ar: "أنت هي سور خلاصنا يا والدة الإله العذراء الحصن المنيع غير المنثلم أبطلي مشورة المعاندين، وحزن عبيدك رديه إلى فرح وحصني مدينتنا (ديرنا) وعن ملوكنا (رؤسائنا) حاربي، وتشفعي عن سلام العالم، لأنك أنت هي رجاؤنا يا والدة الإله (كي نين" } },
      { kind: 'litany', text: { en: "", ar: "، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين" } },
      { kind: 'litany', text: { en: "", ar: "الآن وكل أوان وإلى دهر الداهرين آمين" } },
      { kind: 'litany', text: { en: "", ar: "أيها الملك السمائي المعزى، روح الحق، الحاضر في كل مكان والمالئ الكل، كنز الصالحات، ومعطى الحياة، هلم تفضل وحل فينا، وطهرنا من كل دنس أيها الصالح، وخلص نفوسنا. (ذوكصابتري" } },
      { kind: 'litany', text: { en: "", ar: "كيه إيو كي آجيو ابنيفماتي" } },
      { kind: 'litany', text: { en: "", ar: "المجد للآب والابن والروح القدس" } },
      { kind: 'litany', text: { en: "", ar: "كما كنت مع تلاميذك أيها المخلص وأعطيتهم السلام، هلم أيضا كن معنا وامنحنا سلامك وخلصنا ونج نفوسنا. (كي نين" } },
      { kind: 'litany', text: { en: "", ar: "، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين" } },
      { kind: 'litany', text: { en: "", ar: "الآن وكل أوان وإلى دهر الداهرين آمين" } },
      { kind: 'litany', text: { en: "", ar: "إذا ما وقفنا في هيكلك المقدس نحسب كالقيام في السماء. يا والدة الإله، أنت هي باب السماء، افتحي لنا باب الرحمة." } },
      { kind: 'litany', text: { en: "", ar: "كيري ليسون 41 مرة" } },
      { kind: 'prayer', text: { en: "In the middle of the night I rise to give thanks to You, because of Your righteous judgments. Through the intercessions of the Theotokos, Saint Mary, O Lord, grant us the forgiveness of our sins.", ar: "" } }
    ],
  },
  {
    id: "agpeya-midnight-2",
    title: { en: "Midnight — Second Watch", ar: "نصف الليل — الخدمة الثانية" },
    blocks: [
      { kind: 'rubric', text: { en: "From the Psalms of our father David the prophet and king, may his blessings be upon us all. Amen.", ar: "تتلى مزامير صلاة الغروب ما عدا المزموران الأولان رقميّ 116 و117 كما يلي:" } },
      { kind: 'heading', text: { en: "Psalm 119", ar: "مزمور 119" } },
      { kind: 'psalm', text: { en: "In my own affliction I cried to You, O Lord, and You heard me.", ar: "إليك يا رب صرخت في حزني فاستجبت لي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "O Lord, You shall deliver my soul from unjust lips, and from a deceitful tongue.", ar: "يا رب نج نفسي من الشفاه الظالمة ومن اللسان الغاش." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "What should be given to you, and what should be added to you, a crafty tongue?!", ar: "ماذا تعطى وماذا تزاد من اللسان الغاش." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "The weapons of the mighty are sharpened with coals of the desert!", ar: "سهام الأقوياء مرهفة مع جمر البرية." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Woe to me, that my sojourning is prolonged; I have lived among the dwellings of Kedar.", ar: "ويل لي فإن غربتي قد طالت عليّ، وسكنت في مساكن قيدار." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "My soul has long been a sojourner; I was peaceable among those who hated peace; when I spoke to them, they warred against me without a cause. Alleluia.", ar: "طويلا سكنتْ نفسي في الغربة، ومع مبغضي السلام كنت صاحب سلام، وحين كنت أكلمهم كانوا يقاتلونني باطلا هلليلويا." }, label: { en: "6", ar: "6" } },
      { kind: 'heading', text: { en: "Psalm 120", ar: "مزمور 120" } },
      { kind: 'psalm', text: { en: "I lifted up my eyes to the mountains, from where my help shall come.", ar: "رفعت عيني إلى الجبال، من حيث يأتي عوني." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "My help shall come from the Lord, who made the heaven and the earth.", ar: "معونتي من عند الرب الذي صنع السماء والأرض." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "He will not let your foot be moved; and your keeper will not slumber.", ar: "لا يسلم رجلك للزلل، فما ينعس حافظك." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Behold, He who keeps Israel shall not slumber nor sleep.", ar: "هوذا لا ينعس ولا ينام حارس إسرائيل." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "The Lord shall keep you.", ar: "الرب يحفظك." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "The Lord shall cast a shelter upon your right hand. The sun shall not burn you by day, neither the moon by night.", ar: "الرب يظلل على يدك اليمنى، فلا تحرقك الشمس بالنهار ولا القمر بالليل." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "The Lord shall preserve you from every evil.", ar: "الرب يحفظك من كل سوء." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "The Lord shall keep your soul.", ar: "الرب يحفظ نفسك." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "The Lord shall keep your coming in and your going out, from this time and forever. Alleluia.", ar: "الرب يحفظ دخولك وخروجك، من الآن والي الأبد هلليلويا." }, label: { en: "9", ar: "9" } },
      { kind: 'heading', text: { en: "Psalm 121", ar: "مزمور 121" } },
      { kind: 'psalm', text: { en: "I was glad for those who said to me, \"We will go into the house of the Lord.\"", ar: "فرحت بالقائلين لي إلى بيت الرب نذهب." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Our feet stood in the courts of Jerusalem, Jerusalem which is built as a city that is closely compacted together.", ar: "وقفت أرجلنا في ديار أورشليم، أورشليم المبنية مثل مدينة متصلة بعضها ببعض." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "For there the tribes went up, the tribes of the Lord, as a testimony for Israel, confessing the name of the Lord.", ar: "لأن هناك صعدت القبائل، قبائل الرب، شهادة لإسرائيل، يعترفون لاسم الرب." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "For there are set thrones for judgement, even thrones for the house of David.", ar: "هناك نصبت كراسي للقضاء كراسي بيت داود." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Ask for the things which are for the peace of Jerusalem: and for the prosperity to those who love you.", ar: "اسألوا السلام لأورشليم والخصبَ لمحبيك." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Let peace be within your strength, and prosperity in your heavy towers.", ar: "ليكن السلام في حصنك والخصب في أبراجك الرصينة." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "For the sake of my brothers and my companions, I have indeed spoken peace concerning you. Because of the house of the Lord our God, I have diligently sought good things for you. Alleluia.", ar: "من أجل اخوتي وأقربائي تكلمت من أجلك بالسلام، ومن أجل بيت الرب إلهنا التمست لك الخيرات هلليلويا." }, label: { en: "7", ar: "7" } },
      { kind: 'heading', text: { en: "Psalm 122", ar: "مزمور 122" } },
      { kind: 'psalm', text: { en: "Unto You I have lifted up my eyes, O You who dwell in heaven.", ar: "إليك رفعت عينيّ يا ساكن السماء." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Behold, as the eyes of servants are unto the hands of their masters, and as the eyes of a maidservant to the hands of her mistress.", ar: "فها هما مثل عيون العبيد إلى أيدي مواليهم، ومثل عيني الأمة إلى يدي سيدتها." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "So our eyes are toward the Lord our God until He has pity on us.", ar: "كذلك أعيننا نحو الرب إلهنا حتى يتراءف علينا." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Have mercy on us, O Lord, have mercy on us: for we are exceedingly filled with contempt. And our soul has been exceedingly filled: give the reproach to those who prosper, and contempt to the proud. Alleluia.", ar: "ارحمنا يا رب ارحمنا، فإننا كثيرا ما امتلأنا هوانا، وكثيرا ما امتلأت نفوسنا العار اردده على المخصبين والهوان على المتعظمين هلليلويا." }, label: { en: "4", ar: "4" } },
      { kind: 'heading', text: { en: "Psalm 123", ar: "مزمور 123" } },
      { kind: 'psalm', text: { en: "If it had not been that the Lord is among us, let Israel say; if it had not been that the Lord is among us when men rose up against us, then they would have swallowed us up alive, when their wrath was kindled against us.", ar: "لولا أن الربَّ كان معنا ـ ليقل إسرائيل ـ لولا أن الرب كان معنا عندما قام الناس علينا، لابتلعونا ونحن أحياء، عند سخط غضبهم علينا." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Then the water would have drowned us. Our soul would have gone under the raging flood; then our soul would have gone under the unlimited water.", ar: "إذا لغرقنا في الماء وعبرت نفوسنا السيل، بل جازت نفوسنا الماء الذي لا نهاية له." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Blessed be the Lord, who has not given us for a prey to their teeth.", ar: "مبارك الرب الذي لم يسلمنا فريسة لأسنانهم." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Our soul has been delivered as a sparrow from the snare of the hunters. The snare has broken, and we were delivered. Our help is in the name of the Lord, who made heaven and earth. Alleluia.", ar: "نجت أنفسنا مثل العصفور من فخ الصيادين، الفخ انكسر ونحن نجونا، عوننا باسم الرب الذي صنع السماء والأرض هلليلويا." }, label: { en: "4", ar: "4" } },
      { kind: 'heading', text: { en: "Psalm 124", ar: "مزمور 124" } },
      { kind: 'psalm', text: { en: "Those who trust in the Lord are as Mount Zion: he who dwells in Jerusalem shall never be moved.", ar: "المتوكلون على الرب مثل جبل صهيون لا يتزعزع إلى الأبد، الساكن في أورشليم." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Mountains are round about her, and the Lord is round about His people, from this time and forever.", ar: "الجبال حولها، والرب حول شعبه من الآن والى الأبد." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "For the Lord shall not allow the rod of sinners to be upon the lot of the righteous; lest the righteous might stretch forth their hands to iniquity.", ar: "الرب لا يترك عصا الخطاة تستقر على نصيب الصديقين، لكي لا يمد الصديقون أيديهم إلى الإثم." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Do good, O Lord, to those who are good, and to those who are upright in their heart.", ar: "أحسن يا رب إلى الصالحين والى المستقيمي القلوب." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "But those who turn to stumbles, the Lord will banish with the workers of iniquity.", ar: "أما الذين يميلون إلى العثرات فينزعهم الرب مع فعلة الإثم." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Peace be upon Israel. Alleluia.", ar: "والسلام على إسرائيل هلليلويا." }, label: { en: "6", ar: "6" } },
      { kind: 'heading', text: { en: "Psalm 125", ar: "مزمور 125" } },
      { kind: 'psalm', text: { en: "When the Lord brought back the captivity of Zion, we became as those who were comforted.", ar: "إذا ما رد الرب سبي صهيون صرنا فرحين." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Then our mouth was filled with joy, and our tongue with exultation.", ar: "حينئذ امتلأ فمنا فرحا ولساننا تهليلا." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Then they shall say among the Gentiles, \"The Lord has done great things among them.\"", ar: "حينئذ يقال في الأمم إن الرب قد عظم الصنيع معهم." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "The Lord has done great things for us, we became joyful.", ar: "عظم الرب الصنيع معنا فصرنا فرحين." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "O Lord, You shall bring back our captivity, as the streams in the south.", ar: "اردد يا رب سبينا مثل السيول في الجنوب." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Those who sow in tears shall reap in joy.", ar: "الذين يزرعون بالدموع يحصدون بالابتهاج." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "They went on and wept as they were carrying their seeds; but they shall surely come with exultation, carrying their sheaves. Alleluia.", ar: "سيرا كانوا يسيرون وهم باكون حاملين بذارهم، ويعودون بالفرح حاملين أغمارهم هلليلويا." }, label: { en: "7", ar: "7" } },
      { kind: 'heading', text: { en: "Psalm 126", ar: "مزمور 126" } },
      { kind: 'psalm', text: { en: "Unless the Lord builds the house, those who build it have labored in vain. Unless the Lord guards the city, the watchmen have watched in vain.", ar: "إن لم يبن الرب البيتَ فباطلا تعب البناءون، وإن لم يحرس الرب المدينة فباطلا سهر الحراس." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "It is vain for you to rise early.", ar: "باطل هو لكم التبكير." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Rise up after your sitting, you who eat the bread of grief; while He gives sleep to His beloved.", ar: "انهضوا من بعد جلوسكم يا آكلي الخبز بالهموم، فإنه يمنح أحباءه نوما." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Behold, children are the inheritance of the Lord, the reward of the fruit of the womb.", ar: "البنون ميراث من الرب أجرة ثمرة البطن." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "As arrows in the hand of a mighty man, so are the children of one's youth.", ar: "كالسهام بيد القوي كذلك أبناء المتيقظين." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Blessed is the man who has his quiver full of them.", ar: "مغبوط هو الرجل الذي يملا جعبته منهم." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "They shall not be ashamed when they speak with their enemies in the gates. Alleluia.", ar: "حينئذ لا يخزون إذا كلموا أعداءهم في الأبواب هلليلويا." }, label: { en: "7", ar: "7" } },
      { kind: 'heading', text: { en: "Psalm 127", ar: "مزمور 127" } },
      { kind: 'psalm', text: { en: "Blessed are all who fear the Lord; who walk in His ways.", ar: "طوبى لجميع الذين يتقون الرب السالكين في طرقه." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "You shall eat the fruit of your labors: you shall be blessed, and goodness shall be unto you.", ar: "تأكل من ثمرة أتعابك تصير مغبوطا ويكون لك الخير." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Your wife shall be as a fruitful vine on the sides of your house.", ar: "امرأتك تصير مثلَ كرمة مخصبة في جوانب بيتك." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Your children as young olive-plants round about your table.", ar: "بنوك مثل غروس الزيتون الجدد حول مائدتك." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Behold, thus shall the man be blessed, who fears the Lord.", ar: "هكذا يُبارَك الإنسان المتقي الربَّ." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "The Lord shall bless you out of Zion; and you shall see the good things of Jerusalem all the days of your life. And you shall see the children of your children. Peace be upon Israel.", ar: "يباركك الرب من صهيون، وتبصر خيرات أورشليم جميع أيام حياتك، وترى بني بنيك، والسلام على إسرائيل." }, label: { en: "6", ar: "6" } },
      { kind: 'heading', text: { en: "Psalm 128", ar: "مزمور 128" } },
      { kind: 'psalm', text: { en: "Many times they have warred against me from my youth, let Israel now say. Many times they have warred against me from my youth, and yet they have not prevailed against me.", ar: "مرارا كثيرة حاربوني منذ صباي ـ ليقل إسرائيل ـ مرارا كثيرة قاتلوني منذ شبابي، وإنهم لم يقدروا علي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "The sinners scourged me on my back, and prolonged their iniquity.", ar: "على ظهري جلدني الخطاة وأطالوا إثمهم." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "The Lord is righteous; He has broken the necks of sinners.", ar: "الرب صدّيق هو، يقطع أعناق الخطاة." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Let all who hate Zion be put to shame and turned back. Let them be as the grass of the house-tops, which withers before it is plucked up, with which the reaper does not fill his hand, nor he who gathers up sheaves, his bosom.", ar: "فليخز وليرتد إلى الوراء كل الذين يبغضون صهيون، وليكونوا مثل عشب السطوح الذي ييبَس قبل أن يقطع، الذي لم يملأ الحاصد منه يده، ولا الذي يجمع الغمورَ حضنه." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Neither do they who pass by say, \"The blessing of the Lord be upon you.\"", ar: "ولم يقلْ المجتازون إن بركة الرب عليكم." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "We have blessed you in the name of the Lord. Alleluia.", ar: "باركناكم باسم الرب هلليلويا." }, label: { en: "6", ar: "6" } },
      { kind: 'rubric', text: { en: "Glory to You, O our God. Holy, holy, holy. A reading from the Gospel according to our teacher Saint Luke the Evangelist. May his blessings be with us all. Amen.", ar: "Glory to You, O our God. Holy, holy, holy. A reading from the Gospel according to our teacher Saint Luke the Evangelist. May his blessings be with us all. Amen." } },
      { kind: 'gospel', text: { en: "Luke 7:36-50", ar: "لوقا 7:36-50" }, label: { en: "Gospel", ar: "الإنجيل" } },
      { kind: 'litany', text: { en: "We worship You, O Christ, with Your Good Father and the Holy Spirit, for You have come and saved us. Lord have mercy.", ar: "أعطني يا رب ينابيع دموع كثيرة، كما أعطيت منذ القديم للمرأة الخاطئة. واجعلني مستحقا أن أبل قدميك اللتين أعتقتاني من طريق الضلالة. وأقدم لك طيبا فائقا، وأقتني لي عمرا نقيا بالتوبة. لكي أسمع أنا ذلك الصوت الممتلئ فرحًا: إن إيمانك خلصك (" } },
      { kind: 'litany', text: { en: "Grant us, O Lord, tears of repentance, like the sinful woman who washed Your feet with her tears. Lord have mercy.", ar: "ذوكصابتري" } },
      { kind: 'litany', text: { en: "Her sins, which were many, were forgiven her, for she loved much. Grant us also this love and forgiveness. Lord have mercy.", ar: "كيه إيو كي آجيو ابنيفماتي" } },
      { kind: 'litany', text: { en: "", ar: "المجد للآب والابن والروح القدس" } },
      { kind: 'litany', text: { en: "", ar: "إذا ما تفطنت في كثرة أعمالي الرديئة ويأتي على قلبي فكر تلك الدينونة الرهيبة تأخذني رعدة، فأهرب إليك يا الله محب البشر. فلا تصرف وجهك عني، متضرعا إليك يا من أنت وحدك بلا خطية، أنعم على نفسي المسكينة بتخشع قبل أن يأتي الانقضاء وخلصني (كي نين" } },
      { kind: 'litany', text: { en: "", ar: "، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين" } },
      { kind: 'litany', text: { en: "", ar: "الآن وكل أوان وإلى دهر الداهرين آمين" } },
      { kind: 'litany', text: { en: "", ar: "السموات تطوبك أيتها الممتلئة نعمة، العروس التي بلا زواج. ونحن أيضا نمجد ميلادك غير المدرك. يا والدة الإله يا أم الرحمة والخلاص، تشفعي من أجل خلاص نفوسنا (كي نين" } },
      { kind: 'litany', text: { en: "", ar: "، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين" } },
      { kind: 'litany', text: { en: "", ar: "الآن وكل أوان وإلى دهر الداهرين آمين" } },
      { kind: 'litany', text: { en: "", ar: "أيها الملك السمائي المعزى، روح الحق، الحاضر في كل مكان والمالئ الكل، كنز الصالحات، ومعطى الحياة، هلم تفضل وحل فينا، وطهرنا من كل دنس أيها الصالح، وخلص نفوسنا. (ذوكصابتري" } },
      { kind: 'litany', text: { en: "", ar: "كيه إيو كي آجيو ابنيفماتي" } },
      { kind: 'litany', text: { en: "", ar: "المجد للآب والابن والروح القدس" } },
      { kind: 'litany', text: { en: "", ar: "كما كنت مع تلاميذك أيها المخلص وأعطيتهم السلام، هلم أيضا كن معنا وامنحنا سلامك وخلصنا ونج نفوسنا. (كي نين" } },
      { kind: 'litany', text: { en: "", ar: "، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين" } },
      { kind: 'litany', text: { en: "", ar: "الآن وكل أوان وإلى دهر الداهرين آمين" } },
      { kind: 'litany', text: { en: "", ar: "إذا ما وقفنا في هيكلك المقدس نحسب كالقيام في السماء. يا والدة الإله، أنت هي باب السماء، افتحي لنا باب الرحمة." } },
      { kind: 'litany', text: { en: "", ar: "كيري ليسون 41 مرة" } },
      { kind: 'prayer', text: { en: "I have sinned, O my Lord, I have sinned, and I know my iniquities. But I ask and beseech You: have compassion on me, and forgive me. Through the intercessions of the Theotokos, Saint Mary, O Lord, grant us the forgiveness of our sins.", ar: "" } }
    ],
  },
  {
    id: "agpeya-midnight-3",
    title: { en: "Midnight — Third Watch", ar: "نصف الليل — الخدمة الثالثة" },
    blocks: [
      { kind: 'rubric', text: { en: "From the Psalms of our father David the prophet and king, may his blessings be upon us all. Amen.", ar: "تتلى مزامير صلاة النوم كما يلي:" } },
      { kind: 'heading', text: { en: "Psalm 129", ar: "مزمور 129" } },
      { kind: 'psalm', text: { en: "Out of the depths I have cried to You, O Lord. O Lord, hear my voice.", ar: "من الأعماق صرخت إليك يا رب، يا رب استمع صوتي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Let Your ears be attentive to the voice of my supplication.", ar: "لتكن أذناك مصغيتين إلى صوت تضرعي." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "If You, O Lord, should mark iniquities, O Lord, who shall stand? For through You is forgiveness.", ar: "إن كنت للآثام راصدا يا رب، يا رب من يثبت لأن من عندك المغفرة." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "For Your name's sake I have waited for You, O Lord. My soul has waited for Your law.", ar: "من أجل اسمك صبرْتُ لك يا رب، صبرَتْ نفسي لناموسك." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "My soul has hoped in the Lord, from the morning watch till night.", ar: "انتظرت نفسي الرب من محرس الصبح إلى الليل." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "From the morning watch, let Israel hope in the Lord.", ar: "من محرس الصبح فلينتظر إسرائيل الرب." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "For with the Lord is mercy.", ar: "لأن الرحمة من عند الرب." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "And great is His redemption; and He shall redeem Israel from all his iniquities. Alleluia.", ar: "عظيم هو خلاصه وهو يفتدي إسرائيل من كل آثامه هلليلويا." }, label: { en: "8", ar: "8" } },
      { kind: 'heading', text: { en: "Psalm 130", ar: "مزمور 130" } },
      { kind: 'psalm', text: { en: "O Lord, my heart was not exalted, neither have my eyes been haughtily raised: neither have I walked in great matters, nor in wonders greater than me.", ar: "يا رب لم يرتفع قلبي، ولم تستعلِ عيناي، ولم أسلك في العظائم ولا في العجائب التي هي أعلى مني." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "If I have not humbled myself, but raised my soul, as a weaned child with his mother, so is the recompense upon my soul.", ar: "فان كنت لم أتضع لكن رفعت صوتي مثل الفطيم من اللبن على أمه، كذلك المجازاة على نفسي." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Let Israel hope in the Lord, from now and forever. Alleluia.", ar: "فليتكل إسرائيل على الرب من الآن والى الأبد هلليلويا." }, label: { en: "3", ar: "3" } },
      { kind: 'heading', text: { en: "Psalm 131", ar: "مزمور 131" } },
      { kind: 'psalm', text: { en: "Lord, remember David and all his meekness: how he swore to the Lord, and vowed to the God of Jacob, saying, \"I will not go into the dwelling of my house, or go up to the bed of my couch; I will not give sleep to my eyes, nor slumber to my eyelids, nor rest to my temples, until I find a place for the Lord, and a dwelling place for the God of Jacob.\"", ar: "اذكر يا رب داود وكل دعته، كيف أقسم للرب ونذر لإله يعقوب: إني لا أدخل إلى مسكن بيتي، ولا أصعد على سرير فراشي، ولا أعطى لعيني نوما، ولا لأجفاني نعاسا، ولا راحة لصدغيَّ، إلى أن أجد موضعا للرب ومسكنا لإله يعقوبَ." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Behold, we heard of it in Ephratha; we found it in the fields of the wood.", ar: "ها قد سمعنا به في افراته ووجدناه في موضع الغابة." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Let us enter into His dwelling, and worship at the place where His feet stood.", ar: "فلندخل إلى مساكنه ونسجد في الموضع الذي فيه استقرت قدماه." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Arise, O Lord, into Your rest; You, and the ark of Your holy place.", ar: "قم يا رب إلى راحتك أنت وتابوت موضع قدسك." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Your priests shall clothe themselves with righteousness; and Your righteous shall exult.", ar: "كهنتك يلبسون البر وأبرارك يبتهجون." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "For the sake of Your servant David, do not turn away Your face from Your anointed.", ar: "من أجل داود عبدك لا ترد وجهك عن مسيحك." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "The Lord has sworn in truth to David, and He will not turn from it, \"Of the fruit of your loins I will set upon your throne.\"", ar: "حلف الرب لداود حقا ولا يخلف: لأجعَلنَّ من ثمرة بطنك على كرسيك." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "If your children keep My covenant and My testimonies which I will teach them, their children also will sit upon your throne forever.", ar: "إن حفظ بنوك عهدي وشهاداتي التي أعلمهم إياها، فبنوهم أيضا يجلسون إلى الأبد على كرسيك." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "For the Lord has selected Zion, He has chosen her a dwelling for Himself.", ar: "لأن الرب اختار صهيون ورضيها مسكننا له." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "This is My resting place forever. Here I will dwell; for I have desired it.", ar: "هذا هو موضع راحتي إلى أبد الأبد، ههنا أسكن لأني أردته." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "In blessing I shall bless her hunting. Her poor I shall satisfy with bread. Her priests I shall clothe with salvation; and her saints with rejoicing shall rejoice.", ar: "لصيدها أبارك بركة، لمساكينها أشبع خبزا، لكهنتها ألبس الخلاص وأبرارها يبتهجون ابتهاجا." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "There I shall raise a horn to David.", ar: "هناك أقيم قرنا لداود." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "I have prepared a lamp for My anointed.", ar: "هيأتُ سراجا لمسيحي." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "His enemies I shall clothe with shame, and My holiness shall flourish upon Him. Alleluia.", ar: "لأعدائه ألبس الخزي وعليه يزهر قدسي هلليلويا." }, label: { en: "14", ar: "14" } },
      { kind: 'heading', text: { en: "Psalm 132", ar: "مزمور 132" } },
      { kind: 'psalm', text: { en: "Behold! What is so good, or what so pleasant, as for brothers dwelling together?", ar: "هوذا ما أحسن وما أحلي أن يسكن الاخوة معا." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "It is as ointment upon the head, that came down upon the beard, the beard of Aaron that came down to the fringe of his clothing.", ar: "كالطيب الكائن على الرأس الذي ينزل على اللحية، لحية هارون النازلة على جيب قميصه." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "As the dew of Aermon, that comes down upon the mountain of Zion.", ar: "ومثل ندى حرمون المنحدر على جبل صهيون." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "For there the Lord commanded the blessing and the life forever. Alleluia.", ar: "لأن هناك أمر الرب بالبركة والحياة إلى الأبد هلليلويا." }, label: { en: "4", ar: "4" } },
      { kind: 'heading', text: { en: "Psalm 133", ar: "مزمور 133" } },
      { kind: 'psalm', text: { en: "Behold, bless the Lord, O you the servants of the Lord, who stand in the house of the Lord, in the courts of the house of our God.", ar: "ها باركوا الربَّ يا عبيدَ الرب، القائمين في بيت الرب في ديار إلهنا." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "In the nights lift up your hands unto the Holies, and bless the Lord.", ar: "في الليالي ارفعوا أيديكم إلى القدس وباركوا الرب." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "The Lord shall bless you out of Zion, He who made heaven and earth. Alleluia.", ar: "يبارككم الرب من صهيون الذي خلق السماء والأرض هلليلويا." }, label: { en: "3", ar: "3" } },
      { kind: 'heading', text: { en: "Psalm 136", ar: "مزمور 136" } },
      { kind: 'psalm', text: { en: "By the rivers of Babylon, there we sat and wept when we remembered Zion.", ar: "على أنهار بابل هناك جلسنا، فبكينا عندما تذكرنا صهيون." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "We hung our harps on the willows in the midst of it. For there those who had taken us captive asked of us the words of a song.", ar: "على الصفصاف في وسطها علقنا قيثاراتنا، لأنه هناك سألنا الذين سبونا أقوالَ التسبيح." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "And those who had carried us away asked a hymn, saying, \"Sing us one of the songs of Zion.\"", ar: "والذين استاقونا إلى هناك قالوا: سبحوا لنا تسبحة من تسابيح صهيون." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "How will we sing the Lord's song in a strange land?", ar: "كيف نسبِّح تسبحة الرب في أرض غريبة." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "If I forget you, O Jerusalem, I shall forget my right hand. My tongue shall cling to my throat, if I did not remember you; if I did not prefer Jerusalem as the head of my joy.", ar: "إن نسيتك يا أورشليم أنسَ يميني، ويلتصق لساني بحنكي إن لم أذكرك، إن لم أفضل أورشليم في ابتداء فرحي." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Remember, O Lord, the children of Edom in the day of Jerusalem; who said, \"Tear it down, tear it down, even to its foundations.\"", ar: "اذكر يا رب بني أدوم في يوم أورشليم القائلين: انقضوا انقضوا حتى الأساس منها." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "Wretched daughter of Babylon! Blessed is he who will reward you with the reward you have given us.", ar: "يا بنت بابل الشقية طوبى لمن يكافئك مكافأتك التي جازيتينا." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "Blessed is he who will seize and bury your infants by the rock. Alleluia.", ar: "طوبى لمن يمسك أطفالك ويدفنهم عند الصخرة هلليلويا." }, label: { en: "8", ar: "8" } },
      { kind: 'heading', text: { en: "Psalm 137", ar: "مزمور 137" } },
      { kind: 'psalm', text: { en: "I will confess You, O Lord, with my whole heart, for You have heard all the words of my mouth.", ar: "أعترف لك يا رب من كل قلبي لأنك استمعت كل كلمات فمي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Before the angels I will chant to You. I will worship toward Your holy temple, and confess Your name, on account of Your mercy and Your truth; for You have magnified Your holy name above all.", ar: "أمام الملائكة أرتل لك وأسجد قدام هيكلك المقدس، وأعترف لاسمك على رحمتك وحقك، لأنك قد عظمت اسمك القدوس على الكل." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "The day in which I call upon You, hear me speedily.", ar: "اليوم الذي أدعوك فيه أجبني بسرعة." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "You shall exceedingly look upon my soul with power.", ar: "تكثر التطلع على نفسي بقوة." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Let all the kings of the earth, O Lord, confess You.", ar: "فليعترف لك يا رب كل ملوك الأرض." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "For they have heard all the words of Your mouth. And let them sing in the ways of the Lord.", ar: "لأنهم قد سمعوا سائر كلمات فمك وليسبحوا في طرق الرب." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "For great is the glory of the Lord. The Lord is high, and He regards the lowly; and He knows the existing things from afar off.", ar: "لأن مجد الرب عظيم لأن الرب عال ويعاين المتواضعات والكائنات يعرفها من بعد." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "If I walk in the midst of affliction, You shall revive me.", ar: "إن سلكت في وسط الشدة فإنك تحييني." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "You have stretched forth Your hands against the wrath of enemies, and Your right hand has saved me.", ar: "على رجز الأعداء مددت يدك وخلصتني يمينك." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "O Lord, You shall reward on my behalf: Your mercy, O Lord, endures forever.", ar: "الرب يجازي عني، يا رب رحمتك دائمة إلى الأبد." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "Do not overlook the works of Your hands, O Lord. Alleluia.", ar: "أعمال يديك يا رب لا تتركها هلليلويا." }, label: { en: "11", ar: "11" } },
      { kind: 'heading', text: { en: "Psalm 140", ar: "مزمور 140" } },
      { kind: 'psalm', text: { en: "O Lord, I have cried to You, hear me.", ar: "يا رب إليك صرخت فاستمع لي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Attend to the voice of my supplication when I cry to You.", ar: "أنصت إلى صوت تضرعي، إذا ما صرختُ إليك." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Let my prayer be set forth before You as incense.", ar: "لتستقم صلاتي كالبخور قدامك." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "And the lifting up of my hands as an evening sacrifice.", ar: "وليكن رفع يدي كذبيحة مسائية." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "O Lord, set a watch on my mouth and a strong door for my lips.", ar: "ضع يا رب حافظا لفمي، وبابا حصينا لشفتي." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Do not incline my heart to words of evil, to employ excuses for sins with men who work iniquity; and I shall not agree with their choices.", ar: "ولا تمل قلبي إلى كلام الشر، فيتعلل بعلل في الخطايا مع أناس فاعلي الإثم، ولا أتفق مع مختاريهم." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "The righteous shall chasten me with mercy, and reprove me.", ar: "فليؤدبني الصديق برحمة ويوبخني." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "But do not let the oil of the sinner anoint my head: for yet my prayer also is in their pleasures.", ar: "أما زيت الخاطئ فلا يدهن رأسي، لأن صلاتي أيضا بمسرة." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "Their mighty ones have been swallowed up near the rock: they shall hear my words, for they are delightful.", ar: "قد ابتُلِع أقوياؤهم عند الصخرة، يسمعون كلماتي لأنهم استلذوا." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "As a lump of earth, they are broken upon the ground.", ar: "مثل شحم الأرض انشقوا على الأرض." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "Their bones have been scattered at Hades. For my eyes are to You, O Lord: O Lord, I have hoped in You; do not take away my soul.", ar: "تبددت عظامهم عند الجحيم، لأن عيوننا إليك يا رب، يا رب عليك توكلت فلا تقتل نفسي." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "Keep me from the snare which they have set for me.", ar: "احفظني من الفخ الذي قد نصبوه لي." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "And from the stumbling blocks of those who work iniquity.", ar: "ومن شكوك فاعلي الإثم." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "Sinners shall fall by their own net: I am alone until iniquity passes by. Alleluia.", ar: "يسقط الخطاة في شبكتهم، وأكون أنا وحدي حتى يجوزَ الإثم هلليلويا" }, label: { en: "14", ar: "14" } },
      { kind: 'heading', text: { en: "Psalm 141", ar: "مزمور 141" } },
      { kind: 'psalm', text: { en: "With my voice to the Lord I cried; with my voice to the Lord I made supplication.", ar: "بصوتي إلى الرب صرختُ، بصوتي إلى الرب تضرعتُ." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "I will pour out before Him my supplication.", ar: "أسكب أمامه توسلي." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "My affliction I will pour out before Him, when my spirit was fainting within me, and You knew my paths.", ar: "أبث لديه ضيقي، عند فناء روحي مني وأنت علمتَ سبلي." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "In the way in which I was walking, they hid a snare for me. I looked on my right hand, and beheld, for there was no one who noticed me.", ar: "في الطريق التي أسلك أخفوا لي فخا، تأملت عن اليمين وأبصرت فلم يكن من يعرفني." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Refuge failed me, and there was no one who cared for my soul.", ar: "ضاع المهرب مني وليس من يسأل عن نفسي." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "I cried unto You, O Lord, and said, \"You are my hope, my portion in the land of the living.\"", ar: "فصرختُ إليك يا رب وقلت: أنت هو رجائي وحظي في أرض الأحياء." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "Attend to my supplication, for I am brought very low.", ar: "أنصت إلى طلبتي فإنني قد تذللتُ جدا." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "Deliver me from those who persecute me, for they are stronger than me.", ar: "نجني من الذين يضطهدونني لأنهم قد اعتزوا أكثر مني." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "Bring my soul out of prison, that I may confess Your name, O Lord.", ar: "أخرج من الحبس نفسي، لكي أشكر اسمك يا رب." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "The righteous wait for me until You reward me. Alleluia.", ar: "إياي ينتظر الصديقون حتى تجازيني هلليلويا." }, label: { en: "10", ar: "10" } },
      { kind: 'heading', text: { en: "Psalm 145", ar: "مزمور 145" } },
      { kind: 'psalm', text: { en: "Praise the Lord, O my soul. I will praise the Lord in my life. I will sing praises to my God as long as I exist.", ar: "سبحي يا نفسي الربَّ، أسبح الرب في حياتي وأرتل لإلهي ما دمت موجودا." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Do not trust in the princes, nor in the children of men, in whom there is no salvation.", ar: "لا تتكلوا على الرؤساء ولا على بني البشر الذين ليس عندهم خلاص." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Their spirit shall go forth, and they shall return to their earth.", ar: "تخرج روحهم فيعودون إلى ترابهم." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "In that day all their thoughts shall perish.", ar: "في ذلك اليوم تهلك كافة أفكارهم." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Blessed is he whose helper is the God of Jacob.", ar: "طوبى لمن إله يعقوب معينه." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Whose hope is in the Lord his God: who made heaven and earth, the sea and all things in them.", ar: "واتكاله على الرب إلهه، الذي صنع السماء والأرض والبحر وكل ما فيها." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "Who keeps truth forever: who executes judgement for the oppressed, who gives food to the hungry.", ar: "الحافظ العدل إلى الدهر، الصانع الحكم للمظلومين المعطي الطعام للجياع." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "The Lord looses the bound; the Lord sets up the broken down.", ar: "الرب يحل المربوطين الرب يقيم الساقطين." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "The Lord gives wisdom to the blind.", ar: "الرب يُحَكِّم العميان." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "The Lord loves the righteous.", ar: "الرب يحب الصديقين." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "The Lord preserves the strangers; He accepts the orphan and widow.", ar: "الرب يحفظ الغرباء، ويعضد اليتيم والأرملة." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "But He will destroy the way of sinners.", ar: "ويبيد طرق الخطاة." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "The Lord shall reign forever, and your God, O Zion, from generation to generation. Alleluia.", ar: "يملك الرب إلى الدهر، وإلهك يا صهيون من جيل إلى جيل هلليلويا ." }, label: { en: "13", ar: "13" } },
      { kind: 'heading', text: { en: "Psalm 146", ar: "مزمور 146" } },
      { kind: 'psalm', text: { en: "Praise the Lord, for a psalm is good; let praise be sweet unto our God.", ar: "سبحوا الرب فان المزمور جيد، ولإلهنا يلذ التسبيح." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "The Lord builds up Jerusalem.", ar: "الرب يبني أورشليم." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "And He will gather together the dispersed of Israel.", ar: "الرب يجمع متفرقي إسرائيل." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "He heals the broken-hearted, and binds up all their fractures.", ar: "الرب يشفي المنكسري القلوب، ويجبر جميع كسرهم." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "He numbers the multitudes of stars, and calls them all by names.", ar: "المحصي كثرة الكواكب، ولكافتها يعطي أسماء." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Great is the Lord, and great is His strength; His understanding is infinite.", ar: "عظيم هو الرب وعظيمة هي قوته، ولا إحصاء لفهمه." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "The Lord lifts up the meek, but brings sinners down to the ground.", ar: "الرب يرفع الودعاء ويذل الخطاة إلى الأرض." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "Begin the song to the Lord with thanksgiving; sing praises to our God on the harp.", ar: "ابتدئوا للرب بالاعتراف، رتلوا لإلهنا بالقيثارة." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "He who covers the heaven with clouds; who prepares rain for the earth; who causes grass to spring up on the mountains, and green herb for the service of men; who gives food to the cattle, and to the young ravens that call upon Him.", ar: "الذي يجلل السماء بالغمام، الذي يهيئ للأرض المطر، الذي يُنبت العشب على الجبال، والخضرة لخدمة البشر، ويعطي البهائم طعامها، ولفراخ الغربان التي تدعوه." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "He will not take pleasure in the strength of a horse, nor will He be well-pleased with the legs of man. The Lord will take pleasure in those who fear Him, and in those who hope in His mercy. Alleluia.", ar: "لا يؤْثر قوة الفرس ولا يسر بساقي الرجل، بل يسر الرب بخائفيه وبالراجين رحمته هلليلويا." }, label: { en: "10", ar: "10" } },
      { kind: 'heading', text: { en: "Psalm 147", ar: "مزمور 147" } },
      { kind: 'psalm', text: { en: "Praise the Lord, O Jerusalem; praise your God, O Zion.", ar: "سبحي الرب يا أورشليم، سبحي إلهك يا صهيون." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "For He has strengthened the bars of your gates. He has blessed your children within you.", ar: "لأنه قد قوى مغاليق أبوابك وبارك بنيك فيك." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "He makes your borders peaceful, and fills you with the fatness of wheat.", ar: "الذي جعل تخومَك في سلام، ويملأك من شحم الحنطة." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "He sends His word to the earth: His word runs swiftly.", ar: "الذي يرسل كلمته إلى الأرض فيسرع قوله عاجلا جدا." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "He gives snow like wool: He scatters the mist like ashes. He casts out His ice like morsels.", ar: "المعطي الثلج كالصوف، المذري الضباب كالرماد، ويلقي الجليد مثل الفتات." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Who will be able to stand before His frost?", ar: "قدام وجه برْدِه من يقوم." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "He will send out His word, and melt them. His wind will blow, and the waters shall flow.", ar: "يرسل كلمته فتذيبه، تهب ريحه فتسيل المياه." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "He declares His word to Jacob, His ordinances and judgements to Israel.", ar: "المخبر كلمته ليعقوب وفرائضه وأحكامه لإسرائيل." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "He has not done so with every nation; and He has not revealed to them His judgements. Alleluia.", ar: "لم يصنع هكذا بكل الأمم، وأحكامُه لم يوضحها لهم هلليلويا." }, label: { en: "9", ar: "9" } },
      { kind: 'rubric', text: { en: "Glory to You, O our God. Holy, holy, holy. A reading from the Gospel according to our teacher Saint Luke the Evangelist. May his blessings be with us all. Amen.", ar: "Glory to You, O our God. Holy, holy, holy. A reading from the Gospel according to our teacher Saint Luke the Evangelist. May his blessings be with us all. Amen." } },
      { kind: 'gospel', text: { en: "Luke 12:32-46", ar: "لوقا 12:32-46" }, label: { en: "Gospel", ar: "الإنجيل" } },
      { kind: 'litany', text: { en: "We worship You, O Christ, with Your Good Father and the Holy Spirit, for You have come and saved us. Lord have mercy.", ar: "بعين متحننة يا رب انظر إلى ضعفى، فعما قليل تفنى حياتي، وبأعمالي ليس لي خلاص. فلهذا أسال: بعين رحيمة يا رب انظر إلى ضعفى" } },
      { kind: 'litany', text: { en: "Blessed are those servants whom the Master finds watching when He comes. Lord have mercy.", ar: "ومسكنتي وغربتي، ونجني. (ذوكصابتري" } },
      { kind: 'litany', text: { en: "Be ready, for the Son of Man is coming at an hour you do not expect. Lord have mercy.", ar: "كيه إيو كي آجيو ابنيفماتي" } },
      { kind: 'litany', text: { en: "", ar: "المجد للآب والابن والروح القدس" } },
      { kind: 'litany', text: { en: "", ar: "بما أن الديان حاضر، اهتمي يا نفسي وتيقظي وتفهمي تلك الساعة المخوفة. فإنه ليس رحمة في الدينونة لمن لم يستعمل الرحمة. فلهذا" } },
      { kind: 'litany', text: { en: "", ar: "أشفق عليّ أيها المخلص، فإنك أنت هو محب البشر وحدك (" } },
      { kind: 'litany', text: { en: "", ar: "كي نين" } },
      { kind: 'litany', text: { en: "", ar: "، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين" } },
      { kind: 'litany', text: { en: "", ar: "الآن وكل أوان وإلى دهر الداهرين آمين" } },
      { kind: 'litany', text: { en: "", ar: "يا باب الحياة العقلي، يا والدة الإله المكرمة، خلصي الذين التجأوا إليك بإيمان من الشدائد، لكي نمجد ميلادك الطاهر في كل شيء من أجل خلاص نفوسنا. (" } },
      { kind: 'litany', text: { en: "", ar: "كي نين" } },
      { kind: 'litany', text: { en: "", ar: "، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين" } },
      { kind: 'litany', text: { en: "", ar: "الآن وكل أوان وإلى دهر الداهرين آمين" } },
      { kind: 'litany', text: { en: "", ar: "أيها الملك السمائي المعزى، روح الحق، الحاضر في كل مكان والمالئ الكل، كنز الصالحات، ومعطى الحياة، هلم تفضل وحل فينا، وطهرنا من كل دنس أيها الصالح، وخلص نفوسنا. (ذوكصابتري" } },
      { kind: 'litany', text: { en: "", ar: "كيه إيو كي آجيو ابنيفماتي" } },
      { kind: 'litany', text: { en: "", ar: "المجد للآب والابن والروح القدس" } },
      { kind: 'litany', text: { en: "", ar: "كما كنت مع تلاميذك أيها المخلص وأعطيتهم السلام، هلم أيضا كن معنا وامنحنا سلامك وخلصنا ونج نفوسنا. (كي نين" } },
      { kind: 'litany', text: { en: "", ar: "، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين" } },
      { kind: 'litany', text: { en: "", ar: "الآن وكل أوان وإلى دهر الداهرين آمين" } },
      { kind: 'litany', text: { en: "", ar: "إذا ما وقفنا في هيكلك المقدس نحسب كالقيام في السماء. يا والدة الإله، أنت هي باب السماء، افتحي لنا باب الرحمة." } },
      { kind: 'litany', text: { en: "", ar: "كيريى ليسون 41 مرة" } },
      { kind: 'prayer', text: { en: "Lord, now let Your servant depart in peace, according to Your word, for my eyes have seen Your salvation.", ar: "" } },
      { kind: 'prayer', text: { en: "Through the intercessions of the Theotokos, Saint Mary, O Lord, grant us the forgiveness of our sins. We worship You, O Christ, with Your Good Father and the Holy Spirit, for You have come and saved us. Amen.", ar: "" } },
      { kind: 'prayer', text: { en: "O Lord, Who shall rise at the resurrection of all men, grant us a portion with the righteous in Your kingdom. Through the intercessions of the Theotokos and all Your saints. Amen.", ar: "أيها السيد الرب يسوع المسيح، ابن الله الحي الأزلي، أنر عقولنا لنفهم أقوالك المحيية. وأنهضنا من ظلمة الخطية القاتلة للنفس. واجعلنا أهلا أن نكون مستقيمين في عمل الخير. وفى وقت مجيئك لتدين العالم، فلنستحق سماع ذلك الصوت المملوء فرحا، القائل: تعالوا إلى يا مبارَكي أبى، رثوا الملك المعد لكم من قبل إنشاء العالم. نعم يا رب، سهل لنا أن نكون في تلك الساعة بغير خوف ولا اضطراب ولا سقوط في الدينونة. ولا تجازنا من أجل كثرة آثامنا، لأنك وحدك المتحنن الطويل الأناة الكثير الرحمة، بشفاعة سيدتنا والدة الإله القديسة مريم، وشفاعة جميع مصاف قديسيك. أمين." } },
      { kind: 'prayer', text: { en: "", ar: "ارحمنا يا الله ثم ارحمنا. يا من في كل وقت وكل ساعة، في السماء وعلى الأرض، مسجود له وممجد. المسيح إلهنا الصالح، الطويل الروح، الكثير الرحمة، الجزيل التحنن، الذي يحب الصديقين ويرحم الخطاة الذين أولهم أنا. الذي لا يشاء موت الخاطئ مثل ما يرجع ويحيا. الداعي الكل إلى الخلاص لأجل الموعد بالخيرات المنتظرة." } },
      { kind: 'prayer', text: { en: "", ar: "يا رب اقبل منا في هذه الساعة وكل ساعة طلباتنا. سهل حياتنا، وأرشدنا إلى العمل بوصاياك. قدس أرواحنا. طهر أجسامنا. قوم أفكارنا. نق نياتنا. اشف أمراضنا واغفر خطايانا. ونجنا من كل حزن رديء ووجع قلب. أحطنا بملائكتك القديسين، لكي نكون بمعسكرهم محفوظين ومرشدين، لنصل إلى اتحاد الإيمان وإلى معرفة مجدك غير المحسوس وغير المحدود، فإنك مبارك إلى الأبد. أمين." } },
      { kind: 'prayer', text: { en: "", ar: "نسألك ونشكرك، أيها السيد الرب يسوع المسيح، ابن الله الحي الأزلي، الكائن في النور قبل كل الدهور، نور من نور:" } },
      { kind: 'prayer', text: { en: "", ar: "أنر يا رب عقولنا وقلوبنا، وأضيء أفهامنا، لنفهم كلامك المحيي. وأقمنا من ظلمة الخطية القاتلة للنفس. واجعلنا مستحقين أن نكون مستقيمين في عمل الخير والصلاح. وفي وقت مجيئك الثاني المرهوب، لتدين فيه العالم، فلنستحق سماع ذلك الصوت المملوء فرحا وبهجة، وعزاء وسرورا، ونعيما من فمك الإلهي القائل: \"تعالوا إلي يا مبارَكي أبي، رثوا الملك المعد لكم قبل إنشاء العالم\". نعم أيها الرب إلهنا: وفقنا أن نكون في ذلك اليوم، وتلك الساعة، بغير خوف ولا عيب ولا انزعاج، ولا سقوط ولا انحراف. ولا تؤاخذنا يا رب بكثرة آثامنا. اصفح يا رب عن جميع سيئاتنا وزلاتنا، وغلطاتنا وهفواتنا." } },
      { kind: 'prayer', text: { en: "", ar: "وارفع يا رب عنا وعن جميع العالم، الموت والغلاء، والوباء والفناء، والجلاء وسيف الأعداء، ومؤامرة الشياطين، وشر الحريق والغرق، ومقاومة الأشرار وكيد الفجار، وجور السلطان. وأبطل مؤامرة المعاندين لنا." } },
      { kind: 'prayer', text: { en: "", ar: "اللهم إنك ربنا وإلهنا، تراءف علينا، ولا تطرحنا في بحار المهالك ولا عقاب المسالك. لكن نجنا واحفظنا واسترنا. وأنهضنا من الملل والضجر والتواني والكسل. ولا تدع العدو الشيطان يطغينا بوسع الأمل. بل نبه عقولنا، وأيقظ قلوبنا من نوم الغفلة وتسويف العمر باطلا. اللهم اترك آثامنا واصفح عن زلاتنا. ولا تذكر خطايانا ولا سيئاتنا، ولا تغضب علينا ولا يدم غضبك إلى الأبد. ارحمنا يا رب ثم ارحمنا، فإننا ضعفاء ومساكين، وفي بحار الخطايا غارقين. فإليك نصرخ ولك نسجد وبك نعترف وإليك نرغب. لا تقطع رجاءنا يا سيدي من رحمتك، ولا تغلق باب رحمتك في وجوهنا. بل بفضلك خلصنا، وإلى رحمتك وفقنا، وصوتك الفرح أسمعنا." } },
      { kind: 'prayer', text: { en: "", ar: "اللهم طهرنا وطهر قلوبنا من الأفكار الخبيثة، النجسة الرديئة. وأبطل عنا يا رب وعن كل شعبك، كل الأحلام والخيالات، والهواجس الشيطانية. أقمنا يا الله من كل سقطة وبلية. ثبت فينا يا الله الصبر والرجاء والمحبة والإيمان الأرثوذكسي. واحسبنا من خرافك اليمينية. وأجلسنا مع الذين يتكئون في وليمتك السمائية. واغفر لنا كل إثم وذنب وخطية. وحصّنا بحصن جنود ملائكتك النورانية. فإنه ليس لنا خلاص إلا برحمتك واتكالنا عليك، وإيماننا بك. ورجائنا فيك." } },
      { kind: 'prayer', text: { en: "", ar: "اقبل منا يا رب دعاءنا في هذا الوقت الحاضر، وكل الأوقات. وكل الذين أمرونا وأوصونا أن نذكرهم في الصلوات والقداسات والقناديل والتذكارات، الأحياء منهم والأموات. اذكرنا يا رب نحن وإياهم بالصالحات، في أورشليم السمائية، في ملكوت السموات." } },
      { kind: 'prayer', text: { en: "", ar: "امح يا رب سيئاتنا والذين أساءوا إلينا اترك لهم ولنا. برحمتك يا رب خلص نفوسنا أجمعين. يا رب خلص شعبك. بارك ميراثك. ارعهم وسسهم إلى الأبد. خلص الذين في الشدائد، والضيقات والأحزان. حل المأسورين من رباط الشياطين. أشبع الجياع من الخيرات. عزِّ صغيري القلوب والنفوس. أقم الساقطين. ثبت القائمين. رد الضالين، عل الأرامل والأيتام، أسعف المعوزين. أعطِ بركة لثمار الأرض، مزاجا طيبا للهواء، نموا للأشجار، صعودا كاملا لمياه الأنهار، بارك في الندى والأمطار. أعط قناعة للمحتاجين. أوف عن المديونين. اجمع شتات المتفرقين، اقبل توبة التائبين، اقبل اعتراف المعترفين. أعط فهما للموعوظين. احكم يا رب للمظلومين ." } },
      { kind: 'prayer', text: { en: "", ar: "املأ قلوبنا فرحا وبهجة وعزاء وسرورا ونعيما لكي ما إذا نلنا كفافنا في كل شيء، نتناهى في الأعمال الصالحة المرضية. بارك يا رب في الغلات بالبركات السمائية. بارك يا رب إكليل هذه السنة بصلاحك. بارك يا رب الباذر والزارع، والغارس والحاصد، كما باركت لبني إسرائيل في غلات العام السادس." } },
      { kind: 'prayer', text: { en: "", ar: "بارك يا رب في اجتماعنا هذا، وكل اجتماع الشعوب الأرثوذكسيين. واحفظ لنا وعلينا، حياة وقيام أبينا السيد الأب البطريرك أنبا.. ..، بطريرك هذا الزمان، خلصه يا رب وخلص شعبه من جميع البلايا والتجارب والأحزان. وكذلك شركاءه في الخدمة الرسولية. آباءنا المطارنة، وآباءنا الأساقفة، وآباءنا القمامصة وآباءنا القسوس، وإخوتنا الشمامسة وآباءنا الرهبان، وإخوتنا العلمانيين، والذين أتوا وحضروا واشتركوا معنا في هذه الصلاة. وكل صلوات الأرثوذكسيين الآن طالبين مغفرة خطاياهم، ورحمة لنفوسهم، باركنا وباركهم، حاللنا وحاللهم، اغفر خطايانا وخطاياهم، الماضية والمستأنفة، الذاتية وغير الذاتية، الليلة والنهارية، الظاهرة والخفية." } },
      { kind: 'prayer', text: { en: "", ar: "أدم يا رب عمار المجامع، والكنائس المقدسة، والبراري الأرثوذكسية، والشيوخ الساكنين فيها، وخدامها ومدبريها، ومن بها، واجعل الأمن والسلام والطمأنينة بينهم. وأخضع العدو الشرير تحت أقدامنا وأقدامهم. ولا تجعل له فينا ولا فيهم نصيبا، لا بضربة شمال ولا بضربة يمين. واحفظهم بيدك العالية وذراعك الحصينة. نجنا يا سيدي من التجارب الرديئة، والأشراك المنصوبة المرئية وغير المرئية." } },
      { kind: 'prayer', text: { en: "", ar: "اذكر يا رب آباءنا وأمهاتنا واخوتنا، وأهلنا وأقاربنا ومعلمينا، وأولادنا الروحيين (والجسديين)، وسائر بني المعمودية أجمعين. اذكر يا رب الذين لهم معنا تعب وشركة. اذكر يا رب الذين أكلنا وشربنا من كدهم وتعبهم، وآوونا في منازلهم. وأعطونا من أيديهم. عوضهم يا رب عوض الفانيات بالباقيات، والأرضيات بالسمائيات. املأ بيوتهم ومخازنهم من كل الخيرات، عوضهم يا رب عوض الواحد، ثلاثين وستين ومائة، وغفران خطاياهم في ملكوت السموات. اذكر يا رب الذين أحسنوا إلينا وإلى إخوتنا المساكين، بجميع وجوه الحسنات. محبة فيك وإكراما لاسمك القدوس، باركهم." } },
      { kind: 'prayer', text: { en: "", ar: "اذكر يا رب المهتمين بالصعائد والقرابين والمحرقات والخمر والزيت، والبكور والبخور، والستور والنذور وكتب القراءة وكل أواني المذبح جميعا. عوضهم يا رب عن عطاياهم بغفران خطاياهم. وهب لهم في هذا الدهر الحاضر الحياة الهنيئة وفي الدهر الآتي الحياة الأبدية." } },
      { kind: 'prayer', text: { en: "", ar: "اذكر يا رب آباءنا وإخوتنا الذين سبقوا فرقدوا وتنيحوا في الإيمان المستقيم بالمسيح. نيح يا رب نفوسهم أجمعين، في أحضان آبائنا القديسين إبراهيم وإسحق ويعقوب، في كورة الأحياء، في فردوس النعيم. أما نحن الأحياء فأعنا على خلاص نفوسنا، ودبر حياتنا حسب إرادتك الصالحة." } },
      { kind: 'prayer', text: { en: "", ar: "تفضل يا رب اذكر حقارتي وذلي وضعفي، أنا الخاطئ الشقي غير المستحق الوقوف بين يديك من أجل كثرة خطاياي وذنوبي، لا ترذلني. أقم يا رب قرن خلاص شعبك بإشارة صليبك المحيي. فرجك يا رب عند الشدة وعونك يا رب عند الكرب والذلة. خلصنا يا رب وخلص كل من في شدة. ومرضى شعبك اشفهم." } },
      { kind: 'prayer', text: { en: "", ar: "واجعل يا رب شعبك المسيحيين الحاضرين معنا والغائبين عنا، أن يكونوا مباركين محاللين من فمك الإلهي. من مشارق الشمس إلى مغاربها ومن الشمال إلى اليمين. واقبلنا إليك كما قبلت اللص اليمين، وأنت على خشبة الصليب، ووهبت له فردوس النعيم ." } },
      { kind: 'prayer', text: { en: "", ar: "اذكر يا رب الأيتام والأرامل، والمنقطعين والعاجزين، والذين ليس لهم أحد يذكرهم. اذكرنا يا رب نحن وإياهم في أورشليم السمائية. اذكر يا رب القائمين والقاعدين، والراقدين والمطروحين، والمسافرين في البر والبحر والهواء، والسهل والوعر والأودية، والطرقات ورؤوس الجبال، والتلال والمغاير. والذين في المطابق والسجون، والذين في السبي والنفي، والمأسورين والمربوطين برباط السلاطين والشياطين. ردهم وأت بهم الجميع إلى الميناء، سالمين غانمين، كاسبين رابحين، معافي النفس والجسد والروح." } },
      { kind: 'prayer', text: { en: "", ar: "واجعل يا ربي يسوع المسيح صلاتنا هذه أن تكون مقبولة أمامك بغير رياء ولا كبرياء، ولا عظمة ولا افتخار ولا عيب. أعنا يا الله على رضاك. أعنا على العمل بوصاياك. أعنا على سكرات الموت وما قبل الموت وما بعد الموت. لأنك أنت إله صالح طويل الروح، كثير الرحمة والتحنن. اللهم اجعل باب بيعتك مفتوحا أمام وجوهنا على ممر الدهور والأزمان، وإلى آخر كل زمان. ارحمنا يا الله كعظيم رحمتك." } },
      { kind: 'prayer', text: { en: "", ar: "بشفاعات ذات الشفاعات، معدن الطهر والجود والبركات، سيدتنا كلنا، وفخر جنسنا، العذراء البتول الزكية القديسة مريم، والشهيد المكرم مار مرقس الإنجيلي الرسول كاروز الديار المصرية، وكافة الملائكة والآباء والأنبياء، والرسل والشهداء والقديسين والسواح والعباد، والنساك المجاهدين، والذين أرضوا الرب بأعمالهم الصالحة منذ آدم إلى آخر الدهور." } },
      { kind: 'prayer', text: { en: "", ar: "ولك نسجد أيها الثالوث القدوس الاب والإبن والروح القدس الآن وكل أوان وإلى دهر الداهرين أمين." } },
      { kind: 'prayer', text: { en: "", ar: "اللهم اجعلنا مستحقين أن نقول بشكر:" } },
      { kind: 'prayer', text: { en: "", ar: "أبانا الذي في السموات" } }
    ],
  }
];
